// Success Digital - CTET Paper 2 Question Bank (Upper Primary - Class 6 to 8)
// EXACTLY 20 Unique, Non-Repeating Questions per Test (Tests 1 to 20 = 400 Questions Total)
// Zero mentions of any future year

window.allTestsBank = window.allTestsBank || {};
window.allTestsBank['ctet2'] = {
    1: [
        { subject: "CDP", type: "PYQ", tagText: "Adolescence", question: "According to G. Stanley Hall, the period of adolescence (किशोरावस्था) is famously characterized as a period of:", options: ["Calm and tranquility", "Storm and Stress (वादळ आणि तणाव)", "Physical decay", "Cognitive stagnation"], answer: 1, explanation: "Stanley Hall described adolescence as a turbulent transition characterized by dramatic biological and emotional 'storm and stress'." },
        { subject: "CDP", type: "Concept", tagText: "Piaget", question: "At which Piagetian stage of cognitive development do adolescents develop the ability to formulate abstract hypotheses and test them systematically?", options: ["Sensorimotor", "Pre-operational", "Concrete Operational", "Formal Operational Stage (औपचारिक क्रियात्मक अवस्था)"], answer: 3, explanation: "Formal operations (11+ yrs) enable deductive hypothetical reasoning, abstract thinking, and systematic testing of variables." },
        { subject: "CDP", type: "IMP", tagText: "Sternberg", question: "According to Robert Sternberg's Triarchic Theory of Intelligence, which intelligence involves applying knowledge and adapting effectively to everyday real-world contexts?", options: ["Analytical Intelligence", "Creative Intelligence", "Practical Intelligence (व्यावहारिक बुद्धिमत्ता / Contextual)", "Musical Intelligence"], answer: 2, explanation: "Practical (contextual) intelligence refers to street-smart adaptability to change and practical everyday problem-solving." },
        { subject: "CDP", type: "Pedagogy", tagText: "Metacognition", question: "A middle-school student actively evaluates which study strategies work best for her when preparing for an exam. This demonstrates:", options: ["Rote conditioning", "Metacognition (स्व-संज्ञानात्मक जाणीव / Thinking about one's thinking)", "Egocentric speech", "Trial and error only"], answer: 1, explanation: "Metacognition is the higher-order self-monitoring, planning, and evaluation of one's own cognitive processes." },
        { subject: "Science", type: "Physics", tagText: "Force & Friction", question: "Which of the following types of friction has the least magnitude for the same normal contact force?", options: ["Static friction", "Sliding friction", "Rolling friction (लोळणारे घर्षण)", "Limiting friction"], answer: 2, explanation: "Rolling friction is significantly smaller than sliding and static friction, which is why ball bearings are used in machines." },
        { subject: "Science", type: "Chemistry", tagText: "Acids & Bases", question: "When a turmeric indicator is placed in an alkaline (basic) solution like soap water, its yellow color turns to:", options: ["Blue", "Reddish-brown (तांबूस-तपकिरी)", "Green", "Colorless"], answer: 1, explanation: "Turmeric is a natural indicator that turns reddish-brown in basic solutions and remains yellow in acidic solutions." },
        { subject: "Science", type: "Biology", tagText: "Cell Structure", question: "Which cellular organelle possesses its own DNA and ribosomes and is termed the 'Powerhouse of the Cell'?", options: ["Golgi apparatus", "Endoplasmic reticulum", "Mitochondria (तंतुकणिका)", "Lysosome"], answer: 2, explanation: "Mitochondria have their own circular DNA and synthesize ATP via cellular respiration, powering cellular metabolism." },
        { subject: "Science", type: "Pedagogy", tagText: "Inquiry", question: "In upper primary science classrooms, scientific inquiry is best promoted through:", options: ["Dictating definitions from textbooks", "Hands-on open-ended experimentation and hypothesis testing (हस्तकृती प्रयोग व अन्वेषण)", "Silent memorization of chemical symbols", "Copying diagrams from blackboard"], answer: 1, explanation: "Science inquiry engages students as junior scientists who ask questions, design investigations, and construct evidence-based claims." },
        { subject: "Maths", type: "Algebra", tagText: "Linear Equations", question: "Solve for x: 3(x - 2) + 5 = 2x + 7. What is the value of x?", options: ["6", "8", "10", "4"], answer: 1, explanation: "3x - 6 + 5 = 2x + 7 -> 3x - 1 = 2x + 7 -> 3x - 2x = 7 + 1 -> x = 8." },
        { subject: "Maths", type: "Geometry", tagText: "Triangles", question: "If the three angles of a triangle are in the ratio 2 : 3 : 5, what is the measure of the largest angle?", options: ["60°", "75°", "90°", "100°"], answer: 2, explanation: "2x + 3x + 5x = 180° -> 10x = 180° -> x = 18°. Largest angle = 5x = 5 × 18° = 90°." },
        { subject: "Maths", type: "Arithmetic", tagText: "Exponents", question: "Simplify: (2³)² × 2⁴. What is the expression in single exponent of 2?", options: ["2¹⁰", "2¹⁴", "2²⁴", "2⁸"], answer: 0, explanation: "(2³)² = 2⁶. 2⁶ × 2⁴ = 2⁶⁺⁴ = 2¹⁰." },
        { subject: "Maths", type: "Pedagogy", tagText: "Proof & Logic", question: "In upper primary mathematics, mathematical proof is primarily developed through:", options: ["Rote memorization of theorems", "Deductive logical argumentation and counter-example testing (निगमनात्मक तार्किक युक्तीवाद)", "Intuitive guessing only", "Copying formulas"], answer: 1, explanation: "Upper primary math transitions from empirical observation to rigorous deductive justification and logical proofs." },
        { subject: "Social Science", type: "History", tagText: "Indus Valley", question: "The famous 'Great Bath' (विशाल स्नानगृह) of the Indus Valley Civilization was discovered at which archaeological site?", options: ["Harappa", "Mohenjo-daro (मोहेंजोदडो)", "Lothal", "Kalibangan"], answer: 1, explanation: "The Great Bath was excavated at Mohenjo-daro (Sindh), featuring finely fitted bricks sealed with natural bitumen." },
        { subject: "Social Science", type: "Geography", tagText: "Earth's Layers", question: "Which layer of the Earth has the highest temperature and pressure, composed primarily of Nickel and Iron (NIFE)?", options: ["Crust (भू-कवच)", "Mantle (प्रावरण)", "Core (गाभा)", "Lithosphere"], answer: 2, explanation: "The Earth's core (Centrosphere / NIFE) consists mainly of heavy metallic nickel and iron under extreme pressures." },
        { subject: "Social Science", type: "Civics", tagText: "Constitution", question: "The fundamental feature of Indian secularism (धर्मनिरपेक्षता) implies that:", options: ["The state actively promotes one majority religion", "The state maintains principled distance and equal respect towards all religions", "All religious practices are banned", "Religious leaders govern courts"], answer: 1, explanation: "Indian secularism ensures that the state has no official religion and treats all religious traditions with equal respect and freedom." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Sources", question: "To teach the revolt of 1857, which of the following is considered a 'Primary Source'?", options: ["A modern textbook chapter written in 2015", "Letters, proclamations, and diaries written by soldiers and British officers in 1857", "A historical movie made in 2005", "An encyclopedia summary"], answer: 1, explanation: "Primary sources are direct, firsthand contemporary records created during the historical period being studied." },
        { subject: "Language", type: "Grammar", tagText: "Clauses", question: "Identify the underlined clause: 'The doctor arrived after the patient had died.'", options: ["Noun clause", "Adverb clause of time (कालदर्शक क्रियाविशेषण उपवाक्य)", "Adjective clause", "Principal clause"], answer: 1, explanation: "'After the patient had died' modifies the verb 'arrived' by specifying when it happened, functioning as an Adverb Clause of Time." },
        { subject: "Language", type: "Vocab", tagText: "Idioms", question: "What does the idiom 'To throw down the gauntlet' mean?", options: ["To pick up trash", "To issue a formal challenge (आव्हानाचा स्वीकार करणे / आव्हान देणे)", "To surrender humbly", "To celebrate victory"], answer: 1, explanation: "'To throw down the gauntlet' is a historic idiom meaning to issue a challenge to someone." },
        { subject: "Language", type: "Pedagogy", tagText: "Critical Literacy", question: "Critical reading at the upper primary level involves:", options: ["Accepting all printed statements as absolute truth", "Analyzing author perspective, implicit bias, purpose, and distinguishing facts from opinions", "Reading faster than 300 words a minute", "Copying paragraphs without errors"], answer: 1, explanation: "Critical literacy trains adolescents to deconstruct texts, interrogate underlying biases, and evaluate rhetorical validity." },
        { subject: "Language", type: "Pedagogy", tagText: "Krashen", question: "According to Stephen Krashen's Input Hypothesis, optimal second language acquisition requires input that is:", options: ["Finely tuned to current grammar exercises", "Comprehensible input (i + 1) containing structures slightly ahead of the learner's current level", "Full of difficult archaic vocabulary", "Translated word for word into mother tongue"], answer: 1, explanation: "The 'i + 1' hypothesis states that comprehensible input slightly above the current linguistic level drives unconscious acquisition." }
    ],
    2: [
        { subject: "CDP", type: "PYQ", tagText: "Moral Reasoning", question: "In Lawrence Kohlberg's theory, individuals who make moral decisions based on universal human rights, justice, and conscience rather than societal laws are at:", options: ["Pre-conventional Stage 1", "Conventional Stage 4", "Post-conventional Stage 6 (सार्वत्रिक नैतिक तत्त्वे - पातळी ६)", "Pre-operational stage"], answer: 2, explanation: "Stage 6 represents the pinnacle of moral development where internal universal ethical principles override even civil laws." },
        { subject: "CDP", type: "Concept", tagText: "Vygotsky", question: "Lev Vygotsky argued that when children use 'Private Speech' to talk to themselves while doing difficult math problems, they are:", options: ["Demonstrating cognitive confusion", "Regulating their own cognitive actions and guiding their problem-solving (स्वतःच्या वर्तनाचे नियमन)", "Imitating adults blindly", "Seeking attention"], answer: 1, explanation: "Private speech functions as an internal metacognitive scaffold used for self-guidance and planning." },
        { subject: "CDP", type: "IMP", tagText: "Assessment", question: "Which of the following is an example of 'Assessment AS Learning' in upper primary classes?", options: ["Annual board examinations", "Students engaging in self-reflection using rubrics to assess their own project work (स्व-मूल्यमापन)", "Teacher writing report cards in red ink", "Parent teacher meetings"], answer: 1, explanation: "Assessment as learning actively involves the student in self-monitoring and metacognitive reflection." },
        { subject: "CDP", type: "Inclusive", tagText: "Gifted Adolescent", question: "An intellectually gifted adolescent student who completes standard coursework rapidly should be given:", options: ["Double the amount of the same basic homework", "Curriculum compacting and high-order enrichment projects (अभ्यासक्रम संवर्धन व आव्हानात्मक प्रकल्प)", "Strict punishment to sit still", "Sent out of class"], answer: 1, explanation: "Gifted adolescents require enrichment projects, advanced research, and curriculum acceleration to sustain intellectual curiosity." },
        { subject: "Science", type: "Physics", tagText: "Pressure & Atmosphere", question: "Why does atmospheric pressure decrease as altitude above sea level increases?", options: ["Air becomes hotter", "The column of air above decreases and air density thins out (हवेचे प्रमाण व घनता कमी होते)", "Earth's gravity disappears", "Speed of sound increases"], answer: 1, explanation: "As elevation increases, fewer air molecules remain above to exert weight, lowering atmospheric pressure." },
        { subject: "Science", type: "Chemistry", tagText: "Metals", question: "Which non-metal is a good conductor of electricity due to its free electrons in hexagonal layered sheets?", options: ["Diamond", "Graphite (ग्रॅफाइट)", "Sulfur", "Phosphorus"], answer: 1, explanation: "Graphite has delocalized pi electrons moving freely between its carbon layer planes, making it conduct electricity." },
        { subject: "Science", type: "Biology", tagText: "Microorganisms", question: "Yeast converts sugar into alcohol during bread and beer making. This anaerobic metabolic process is called:", options: ["Pasteurization", "Fermentation (किण्वन / आंबवणे)", "Nitrogen fixation", "Photosynthesis"], answer: 1, explanation: "Fermentation is anaerobic biochemical breakdown of glucose into ethanol and carbon dioxide by yeast enzymes." },
        { subject: "Science", type: "Pedagogy", tagText: "Nature of Science", question: "Which statement reflects the true nature of science?", options: ["Science is a static collection of absolute permanent facts", "Scientific knowledge is tentative, evidence-based, and subject to revision with new discoveries (पुरावा-आधारित व परिवर्तनशील)", "Scientific theories never change", "Science has nothing to do with questioning"], answer: 1, explanation: "Scientific knowledge is dynamic, empirical, falsifiable, and evolves as new experimental evidence emerges." },
        { subject: "Maths", type: "Algebra", tagText: "Factorisation", question: "Factorise the quadratic expression: x² - 7x + 12.", options: ["(x - 3)(x - 4)", "(x + 3)(x + 4)", "(x - 2)(x - 6)", "(x - 1)(x - 12)"], answer: 0, explanation: "-3 × -4 = +12, and -3 + (-4) = -7. Thus, x² - 7x + 12 = (x - 3)(x - 4)." },
        { subject: "Maths", type: "Geometry", tagText: "Polygons", question: "What is the sum of the interior angles of a regular pentagon (5 sides)?", options: ["360°", "540° (५४० अंश)", "720°", "180°"], answer: 1, explanation: "Sum of interior angles = (n - 2) × 180° = (5 - 2) × 180° = 3 × 180° = 540°." },
        { subject: "Maths", type: "Statistics", tagText: "Averages", question: "What is the median of the data set: 13, 18, 11, 25, 17, 19, 14?", options: ["14", "17", "18", "19"], answer: 1, explanation: "Arranging in ascending order: 11, 13, 14, 17, 18, 19, 25. The middle value (4th item) is 17." },
        { subject: "Maths", type: "Pedagogy", tagText: "Misconceptions", question: "A student incorrectly states: '-5 is greater than -2'. The teacher should address this misconception by using:", options: ["A number line showing that numbers further to the right are greater (संख्यारेषेचा वापर)", "Punishing the student with 10 pushups", "Giving a failing mark on the test", "Ignoring the error"], answer: 0, explanation: "A number line concretely visualizes that -2 lies to the right of -5, demonstrating that -2 > -5." },
        { subject: "Social Science", type: "History", tagText: "Mughal Empire", question: "Who wrote 'Akbarnama' (and Ain-i-Akbari), the official detailed chronicle of Emperor Akbar's reign?", options: ["Abul Fazl (अबुल फझल)", "Birbal", "Faizi", "Badauni"], answer: 0, explanation: "Akbar's court historian and vizier Abul Fazl authored the monumental three-volume Akbarnama." },
        { subject: "Social Science", type: "Geography", tagText: "Tectonic Plates", question: "The Himalayas were formed as fold mountains due to the collision between which two tectonic plates?", options: ["Pacific Plate and North American Plate", "Indian Plate and Eurasian Plate (भारतीय व युरेशियन भूपट्ट)", "African Plate and South American Plate", "Nazca Plate and Cocos Plate"], answer: 1, explanation: "The ongoing collision of the northward-moving Indian tectonic plate with the Eurasian plate uplifted the Himalayas." },
        { subject: "Social Science", type: "Civics", tagText: "Judiciary", question: "Which article of the Indian Constitution empowers the Supreme Court to issue writs for the enforcement of Fundamental Rights?", options: ["Article 21", "Article 32 (कलम ३२)", "Article 44", "Article 51A"], answer: 1, explanation: "Article 32 gives citizens the right to petition the Supreme Court directly via writs (Habeas Corpus, Mandamus, etc.)." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Field Trips", question: "Organizing a field trip to a local historical monument or museum helps upper primary students primarily by:", options: ["Spending school funds", "Connecting textbook concepts to tangible concrete historical evidence and spatial heritage", "Giving teachers a free day", "Avoiding exams"], answer: 1, explanation: "Field trips offer experiential learning, bringing abstract historical timelines and architecture to concrete life." },
        { subject: "Language", type: "Grammar", tagText: "Voice", question: "Change to Passive Voice: 'The mechanic has repaired the car.'", options: ["The car has been repaired by the mechanic.", "The car was repaired by mechanic.", "The car had been repaired.", "Mechanic was repaired car."], answer: 0, explanation: "Present perfect active takes 'has/have + been + V3 (repaired)' in passive voice." },
        { subject: "Language", type: "Vocab", tagText: "Antonym", question: "Choose the antonym of 'Meticulous':", options: ["Careless / Sloppy (निष्काळजी)", "Thorough", "Precise", "Accurate"], answer: 0, explanation: "'Meticulous' means showing great attention to detail; its opposite is 'Careless' or 'Sloppy'." },
        { subject: "Language", type: "Pedagogy", tagText: "Multilingualism", question: "In a middle school classroom, recognizing students' diverse mother tongues as a pedagogical resource:", options: ["Creates cognitive chaos", "Validates learner identities and enriches cognitive-linguistic flexibility across languages", "Slows down English learning permanently", "Violates school rules"], answer: 1, explanation: "Multilingualism serves as an additive cognitive asset, facilitating metalinguistic awareness and concept mastery." },
        { subject: "Language", type: "Pedagogy", tagText: "Writing Process", question: "The 'Revising' stage of the writing process focuses primarily on:", options: ["Checking capital letters only", "Reorganizing ideas, clarifying paragraph structure, and strengthening thesis arguments", "Printing final copies", "Looking up words in a rhyming dictionary"], answer: 1, explanation: "Revision tackles macro-structure: coherence, clarity of argument, organization, and voice of ideas." }
    ],
    3: [
        { subject: "CDP", type: "PYQ", tagText: "Gardner", question: "According to Howard Gardner, an architect or a cartographer (mapmaker) possesses high:", options: ["Bodily-Kinesthetic Intelligence", "Spatial Intelligence (अवकाशीय बुद्धिमत्ता)", "Musical Intelligence", "Intrapersonal Intelligence"], answer: 1, explanation: "Spatial intelligence involves mental manipulation of 3D configurations, mental imagery, and spatial visualization." },
        { subject: "CDP", type: "Concept", tagText: "Erikson", question: "According to Erik Erikson, the central psychosocial conflict of the adolescent stage (12 to 18 years) is:", options: ["Industry vs Inferiority", "Identity vs Role Confusion (ओळख वि. भूमिका गोंधळ)", "Intimacy vs Isolation", "Generativity vs Stagnation"], answer: 1, explanation: "Adolescents grapple with identity development: 'Who am I, and what is my place and values in society?'" },
        { subject: "CDP", type: "IMP", tagText: "Peer Influence", question: "During adolescence, peer conformity and peer groups exert strong influence on:", options: ["Dress, music taste, and social leisure activities (सामाजिक जीवनशैली व आवडीनिवडी)", "Basic ethical foundations instilled by family", "Biological DNA", "Height growth"], answer: 0, explanation: "Peer groups heavily influence adolescent socialization, dress, language idioms, and music preferences." },
        { subject: "CDP", type: "Pedagogy", tagText: "Continuous Evaluation", question: "A portfolio containing a student's self-selected best science lab reports, essays, and art pieces with reflective notes is an example of:", options: ["Standardized psychometric test", "Authentic developmental assessment (वास्तववादी सर्वंकष मूल्यमापन)", "Summative punishment", "IQ screening"], answer: 1, explanation: "A student portfolio provides authentic qualitative evidence of developmental achievement and metacognitive reflection." },
        { subject: "Science", type: "Physics", tagText: "Light Reflection", question: "When a light ray strikes a plane mirror at an angle of incidence of 35°, what is the angle of reflection?", options: ["55°", "35° (३५ अंश)", "70°", "90°"], answer: 1, explanation: "By the First Law of Reflection, the angle of incidence equals the angle of reflection (i = r = 35°)." },
        { subject: "Science", type: "Chemistry", tagText: "Combustion", question: "Which chemical compound is widely used in soda-acid fire extinguishers because it releases carbon dioxide gas upon reacting with acid?", options: ["Sodium chloride", "Sodium bicarbonate / Baking soda (NaHCO₃)", "Calcium carbonate", "Copper sulfate"], answer: 1, explanation: "Sodium bicarbonate reacts with sulfuric acid in fire extinguishers to produce high-pressure CO₂ foam that smothers fires." },
        { subject: "Science", type: "Biology", tagText: "Plant Reproduction", question: "The transfer of pollen grains from the anther to the stigma of a flower is called:", options: ["Fertilization", "Pollination (परागकण / परागीभवन)", "Germination", "Transpiration"], answer: 1, explanation: "Pollination is the mechanical transfer of pollen from male anther to female stigma by wind, water, or insects." },
        { subject: "Science", type: "Pedagogy", tagText: "Misconception", question: "Students often believe that 'heavy objects fall faster than light objects in air' because of gravity. How can a teacher best dispel this misconception?", options: ["Telling them they are wrong", "Demonstrating the coin and feather fall in a vacuum tube (निर्वात नळीतील प्रयोग)", "Giving them a negative score", "Avoiding gravity in class"], answer: 1, explanation: "The classic guinea-and-feather vacuum tube experiment proves that in absence of air resistance, all objects accelerate equally under gravity." },
        { subject: "Maths", type: "Algebra", tagText: "Identities", question: "Expand the algebraic identity: (2x + 3y)².", options: ["4x² + 9y²", "4x² + 12xy + 9y²", "2x² + 6xy + 3y²", "4x² + 6xy + 9y²"], answer: 1, explanation: "(a + b)² = a² + 2ab + b² -> (2x)² + 2(2x)(3y) + (3y)² = 4x² + 12xy + 9y²." },
        { subject: "Maths", type: "Geometry", tagText: "Pythagoras", question: "In a right-angled triangle, if the two legs are 6 cm and 8 cm, what is the length of the hypotenuse?", options: ["10 cm (१० सेमी)", "12 cm", "14 cm", "100 cm"], answer: 0, explanation: "Hypotenuse² = 6² + 8² = 36 + 64 = 100. Hypotenuse = √100 = 10 cm." },
        { subject: "Maths", type: "Arithmetic", tagText: "Ratio", question: "If 12 men can complete a construction project in 20 days, how many days will 15 men take at the same rate?", options: ["14 days", "16 days (१६ दिवस)", "18 days", "25 days"], answer: 1, explanation: "Inverse variation: Men × Days = constant -> 12 × 20 = 15 × d -> 240 = 15d -> d = 240 ÷ 15 = 16 days." },
        { subject: "Maths", type: "Pedagogy", tagText: "Divergent Question", question: "Which of the following is a divergent, open-ended question in middle school mathematics?", options: ["What is 7 × 8?", "Find the area of a rectangle with length 6 cm and breadth 4 cm.", "Design three different rectangles that each have an area of 24 square centimeters.", "Is 29 a prime number?"], answer: 2, explanation: "Designing multiple rectangles with area 24 (1×24, 2×12, 3×8, 4×6) prompts divergent exploration of factors and dimensions." },
        { subject: "Social Science", type: "History", tagText: "Bhakti & Sufi", question: "Who composed the sacred poetry collection 'Bijak' (बीजक) criticizing rituals and preaching unity of God?", options: ["Kabir (संत कबीर)", "Mirabai", "Tulsidas", "Guru Nanak"], answer: 0, explanation: "Bijak is the famous philosophical compilation of Sant Kabir's couplets (dohas) attacking hollow religious orthodoxy." },
        { subject: "Social Science", type: "Geography", tagText: "Atmosphere", question: "The Ozone layer, which shields the Earth from harmful ultraviolet solar radiation, is located in the:", options: ["Troposphere", "Stratosphere (स्थितांबर)", "Mesosphere", "Thermosphere"], answer: 1, explanation: "The stratosphere contains the concentrated ozone layer (ozonosphere) that absorbs destructive UV rays." },
        { subject: "Social Science", type: "Civics", tagText: "Parliament", question: "How many members of the Rajya Sabha are nominated by the President of India for distinction in literature, science, art, and social service?", options: ["2 members", "10 members", "12 members (१२ सदस्य)", "15 members"], answer: 2, explanation: "Under Article 80 of the Constitution, the President nominates 12 distinguished members to the Rajya Sabha." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Controversial Issues", question: "When addressing sensitive or controversial social issues (like caste discrimination) in class, the teacher should:", options: ["Avoid the topic completely", "Facilitate a respectful, evidence-based dialogue anchored in constitutional values and dignity", "Take sides aggressively", "Mock students who ask questions"], answer: 1, explanation: "Pedagogic discussions on sensitive issues should be grounded in constitutional values of human dignity, empathy, and evidence." },
        { subject: "Language", type: "Grammar", tagText: "Reported Speech", question: "She said to him, 'Please help me carry this box.' Indirect form:", options: ["She requested him to help her carry that box.", "She told him please help her.", "She ordered him to carry box.", "She asked that he help carry this box."], answer: 0, explanation: "Imperative request takes 'requested + object + to + V1', and 'this' shifts to 'that'." },
        { subject: "Language", type: "Vocab", tagText: "One Word", question: "An official pardon granted to people convicted of political offenses is called an:", options: ["Amnesty (सार्वजनिक माफी/राजकीय माफी)", "Alimony", "Armistice", "Autocracy"], answer: 0, explanation: "'Amnesty' is an official government pardon for people convicted of political offenses." },
        { subject: "Language", type: "Pedagogy", tagText: "Grammar in Context", question: "Which is the most effective way to teach grammatical passive voice to Grade 7 students?", options: ["Making them chant the rule table 50 times", "Using authentic news reports and scientific experiment descriptions where the action matters more than the agent", "Banning passive voice in speech", "Translating sentences into Latin"], answer: 1, explanation: "Passive voice naturally functions in scientific lab reports and journalism where focus rests on the process rather than actor." },
        { subject: "Language", type: "Pedagogy", tagText: "Reading Strategy", question: "The 'SQ3R' study reading method stands for:", options: ["Scan, Query, Read, Write, Repeat", "Survey, Question, Read, Recite, Review (पाहणी, प्रश्न, वाचन, कथन, पुनरावलोकन)", "Speed, Quick, Read, Review, Record", "Silent, Quality, Read, Revise, Retell"], answer: 1, explanation: "Francis Robinson's SQ3R framework comprises Survey, Question, Read, Recite, and Review." }
    ],
    4: [
        { subject: "CDP", type: "PYQ", tagText: "Vygotsky", question: "According to Vygotsky, the distance between what a student can achieve independently and what can be achieved under adult guidance or peer collaboration is:", options: ["Schema", "Zone of Proximal Development - ZPD (समीपस्थ विकासाचे क्षेत्र)", "Equilibrium", "Object Permanence"], answer: 1, explanation: "ZPD defines the fertile cognitive boundary where assisted learning produces new independent competence." },
        { subject: "CDP", type: "Concept", tagText: "Piaget", question: "A Grade 8 student solves an algebra problem by systematically isolating variables and checking possible solutions mentally. This demonstrates:", options: ["Pre-operational Centration", "Hypothetico-Deductive Reasoning (काल्पनिक-निगमनात्मक तर्क)", "Animistic thinking", "Sensory-motor reflexes"], answer: 1, explanation: "Hypothetico-deductive reasoning is the hallmark of Piaget's Formal Operational Stage." },
        { subject: "CDP", type: "IMP", tagText: "Self-Concept", question: "An adolescent's self-concept becomes increasingly complex because it integrates:", options: ["Only physical appearance", "Contradictory traits, future aspirations, psychological motives, and social roles", "Only parental expectations", "Scores on school tests alone"], answer: 1, explanation: "Adolescent self-identity expands to incorporate multidimensional, psychological, and relational self-perceptions." },
        { subject: "CDP", type: "Pedagogy", tagText: "Bloom Taxonomy", question: "In Bloom's Revised Taxonomy, which of the following tasks represents the highest cognitive level ('Creating')?", options: ["Listing the formulas for density", "Designing an innovative solar water purification system for a village (नवीन मॉडेल तयार करणे)", "Explaining how an electric motor works", "Calculating the speed of a car"], answer: 1, explanation: "'Creating' involves synthesizing diverse concepts to generate an original design, plan, or product." },
        { subject: "Science", type: "Physics", tagText: "Electricity", question: "In a domestic electric circuit, what is the primary safety purpose of using a fuse wire or MCB?", options: ["To save electricity bills", "To break the circuit automatically when current exceeds safe limits (अतिप्रवाह झाल्यास वीजपुरवठा खंडित करणे)", "To make light bulbs brighter", "To convert AC to DC"], answer: 1, explanation: "A fuse or MCB melts or trips during overcurrent or short-circuits, preventing electrical fires and appliance damage." },
        { subject: "Science", type: "Chemistry", tagText: "Metals & Non-metals", question: "Why is sodium metal stored immersed in kerosene in school chemistry laboratories?", options: ["To keep it cool", "Because it reacts violently with atmospheric oxygen and water vapor, catching fire (हवा व पाण्याशी अतिशय तीव्र अभिक्रिया)", "To dissolve it into liquid", "To prevent evaporation"], answer: 1, explanation: "Sodium is highly reactive; it oxidizes vigorously in air and reacts explosively with water, so it is preserved in kerosene." },
        { subject: "Science", type: "Biology", tagText: "Photosynthesis", question: "In green leaves, which tiny microscopic pores surrounded by guard cells regulate gas exchange and transpiration?", options: ["Xylem vessels", "Stomata (पर्णरंध्रे)", "Phloem sieve tubes", "Chloroplasts"], answer: 1, explanation: "Stomata are specialized leaf pores regulated by guard cells for exchanging CO₂/O₂ and releasing water vapor." },
        { subject: "Science", type: "Pedagogy", tagText: "Assessment", question: "Which assessment technique is most effective for evaluating students' scientific process skills (like observing, measuring, and predicting)?", options: ["A written pen-and-paper essay", "Practical performance-based lab tasks with observational rubrics (प्रात्यक्षिक प्रयोग मूल्यमापन)", "Multiple-choice definition recall", "Oral spelling contest"], answer: 1, explanation: "Scientific process skills can only be authentically assessed through hands-on practical lab performance." },
        { subject: "Maths", type: "Arithmetic", tagText: "Compound Interest", question: "Find the compound interest on ₹8,000 for 2 years at 10% per annum compounded annually.", options: ["₹1,600", "₹1,680 (१,६८० रुपये)", "₹1,800", "₹9,680"], answer: 1, explanation: "Amount = 8000 × (1.10)² = 8000 × 1.21 = ₹9,680. CI = 9,680 - 8,000 = ₹1,680." },
        { subject: "Maths", type: "Geometry", tagText: "Cylinder", question: "What is the formula for the curved surface area of a right circular cylinder of radius r and height h?", options: ["πr²h", "2πrh (२πrh)", "2πr(r + h)", "4πr²"], answer: 1, explanation: "Curved surface area of a cylinder = circumference of base × height = 2πrh." },
        { subject: "Maths", type: "Algebra", tagText: "Indices", question: "What is the value of 5⁰ + 3⁻¹ × 3?", options: ["0", "1", "2", "6"], answer: 2, explanation: "5⁰ = 1. 3⁻¹ = 1/3. Thus, 1 + (1/3 × 3) = 1 + 1 = 2." },
        { subject: "Maths", type: "Pedagogy", tagText: "Van Hiele", question: "At which Van Hiele level do students understand the role of axioms, definitions, and theorems, constructing formal deductive geometric proofs?", options: ["Level 0 (Visualization)", "Level 1 (Analysis)", "Level 2 (Informal Deduction)", "Level 3 (Formal Deduction / औपचारिक निगमन)"], answer: 3, explanation: "At Level 3 (Formal Deduction), students construct axiomatic mathematical proofs using deductive logic." },
        { subject: "Social Science", type: "History", tagText: "Colonial Rule", question: "Who introduced the 'Permanent Settlement' (कायमधारा पद्धत) revenue system in Bengal in 1793?", options: ["Lord Cornwallis (लॉर्ड कॉर्नवॉलिस)", "Warren Hastings", "Lord Dalhousie", "Lord Wellesley"], answer: 0, explanation: "Lord Cornwallis enacted the Permanent Settlement of 1793, turning zamindars into hereditary landowners." },
        { subject: "Social Science", type: "Geography", tagText: "Ocean Currents", question: "Warm ocean currents originate near the equator and move towards the:", options: ["Poles (ध्रुवांकडे)", "Equator again", "Tropic of Capricorn only", "Deep ocean floor"], answer: 0, explanation: "Warm currents carry thermal energy from the hot tropical equator poleward, moderating coastal climates." },
        { subject: "Social Science", type: "Civics", tagText: "Federalism", question: "In the Indian federal system, which government has the exclusive constitutional power to legislate on subjects in the 'Union List'?", options: ["State governments only", "Central Parliament (केंद्रीय संसद)", "Panchayats only", "High Courts"], answer: 1, explanation: "The Union Parliament holds exclusive jurisdiction over Union List subjects (Defense, Foreign Affairs, Railways, Banking)." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Role Play", question: "Organizing a mock 'Youth Parliament' (युवा संसद) in middle school social science develops:", options: ["Aggression and shouting", "Deep experiential understanding of parliamentary debate, law-making, and democratic citizenship", "Disdain for government", "Wasted study time"], answer: 1, explanation: "Mock parliaments foster civic engagement, argumentation, consensus building, and democratic empathy." },
        { subject: "Language", type: "Grammar", tagText: "Transformation", question: "Transform to comparative: 'Iron is the most useful metal.'", options: ["Iron is more useful than any other metal.", "Iron is useful metal.", "No other metal is as useful as iron.", "Iron is more useful of all."], answer: 0, explanation: "'the most useful' transforms to comparative 'more useful than any other metal'." },
        { subject: "Language", type: "Vocab", tagText: "Prefix", question: "Which prefix added to 'Credible' forms its exact antonym?", options: ["Dis-", "In- (Incredible)", "Un-", "Mis-"], answer: 1, explanation: "'In-' + 'credible' = 'Incredible' (unbelievable or extraordinary)." },
        { subject: "Language", type: "Pedagogy", tagText: "Reading Comprehension", question: "Inferential comprehension requires a reader to:", options: ["Read only the literal words printed on page", "Read between the lines and draw logical conclusions not explicitly stated (गर्भित अर्थ ओळखणे)", "Translate every sentence", "Memorize word counts"], answer: 1, explanation: "Inferential comprehension synthesizes textual clues and background knowledge to deduce implicit meanings." },
        { subject: "Language", type: "Pedagogy", tagText: "Peer Tutoring", question: "Peer tutoring in adolescent English classrooms benefits the tutor because it:", options: ["Gives the tutor a chance to punish friends", "Deepens the tutor's own conceptual clarity, communication skills, and metacognition", "Takes away teacher salary", "Is purely entertaining"], answer: 1, explanation: "Explaining and clarifying ideas to peers consolidates the tutor's own linguistic schemata and communicative confidence." }
    ],
    5: [
        { subject: "CDP", type: "PYQ", tagText: "Information Processing", question: "The Information Processing Approach compares human cognitive functioning to a:", options: ["Hydraulic pump", "Computer processing information (input -> storage -> retrieval) (संगणकासारखी माहिती प्रक्रिया)", "Biological muscle", "Wax tablet"], answer: 1, explanation: "Information processing conceptualizes cognition as encoding, working memory storage, and strategic retrieval like a computer." },
        { subject: "CDP", type: "Concept", tagText: "Adolescent Egocentrism", question: "David Elkind described the adolescent conviction that one is uniquely invulnerable and completely special as the:", options: ["Imaginary Audience", "Personal Fable (वैयक्तिक कथा / अजेय असल्याची भावना)", "Centration", "Conservation"], answer: 1, explanation: "The 'Personal Fable' is the adolescent belief in their uniqueness and invulnerability ('it won't happen to me')." },
        { subject: "CDP", type: "IMP", tagText: "Motivation", question: "According to Bernard Weiner's Attribution Theory, attributing success to 'Hard Work and Effort' reflects an attribution that is:", options: ["External and uncontrollable", "Internal and controllable (अंतर्गत व नियंत्रणीय)", "External and stable", "Pure luck"], answer: 1, explanation: "Effort is internal and controllable, fostering healthy academic self-efficacy and resilience." },
        { subject: "CDP", type: "Inclusive", tagText: "Hearing Impairment", question: "To effectively teach an adolescent with partial hearing impairment in a regular classroom, the teacher should:", options: ["Always speak facing the blackboard", "Face the class while speaking so lip reading and facial cues are visible, and use visual captions", "Speak in an angry scream", "Exclude the student from discussions"], answer: 1, explanation: "Maintaining clear visual sightlines enables lip-reading and non-verbal gestural cues that assist auditory decoding." },
        { subject: "Science", type: "Physics", tagText: "Sound", question: "The loudness of a sound is directly determined by which characteristic of its sound wave?", options: ["Frequency", "Amplitude of vibration (कंपनाचा आयाम)", "Speed of wave", "Wavelength only"], answer: 1, explanation: "Loudness is proportional to the square of amplitude; larger amplitude produces louder sounds, while frequency determines pitch." },
        { subject: "Science", type: "Chemistry", tagText: "Chemical Reactions", question: "Rusting of iron in moist air is an example of an exothermic redox reaction where iron is:", options: ["Reduced", "Oxidized (ऑक्सिडीकरण)", "Decomposed", "Electrolyzed"], answer: 1, explanation: "Iron reacts with oxygen and moisture to form hydrated iron oxide (rust), undergoing oxidation." },
        { subject: "Science", type: "Biology", tagText: "Endocrine", question: "Which endocrine gland attached to the base of the brain regulates growth and controls other glands, known as the 'Master Gland'?", options: ["Thyroid gland", "Pituitary gland (पियुषिका ग्रंथी / Master Gland)", "Adrenal gland", "Pancreas"], answer: 1, explanation: "The pituitary gland secretes growth hormone and tropic hormones directing thyroid, adrenals, and gonads." },
        { subject: "Science", type: "Pedagogy", tagText: "Scientific Temper", question: "Developing 'Scientific Temper' (वैज्ञानिक दृष्टिकोन) in school students implies nurturing:", options: ["Blind belief in superstitions", "Critical questioning, rational inquiry, objective evidence-seeking, and open-mindedness", "Memorizing every science formula", "Ignoring environmental issues"], answer: 1, explanation: "Scientific temper is a mindset of critical skepticism, rational logic, and evidence-based inquiry free of dogma." },
        { subject: "Maths", type: "Arithmetic", tagText: "Percentages", question: "In an examination, 85% of students passed. If 75 students failed, how many total students appeared for the examination?", options: ["400", "500 (५०० विद्यार्थी)", "600", "750"], answer: 1, explanation: "Failed percentage = 100% - 85% = 15%. 15% of Total = 75 -> Total = (75 × 100) ÷ 15 = 500." },
        { subject: "Maths", type: "Geometry", tagText: "Circles", question: "What is the area of a circle with a diameter of 14 cm? (Take π = 22/7)", options: ["44 sq. cm", "154 sq. cm (१५४ चौ. सेमी)", "88 sq. cm", "616 sq. cm"], answer: 1, explanation: "Radius r = 14 ÷ 2 = 7 cm. Area = πr² = (22/7) × 7 × 7 = 154 sq. cm." },
        { subject: "Maths", type: "Algebra", tagText: "Linear Equations", question: "Solve the linear equation: 5y - 7 = 3y + 9. What is y?", options: ["6", "8 (y = ८)", "10", "4"], answer: 1, explanation: "5y - 3y = 9 + 7 -> 2y = 16 -> y = 16 ÷ 2 = 8." },
        { subject: "Maths", type: "Pedagogy", tagText: "Dienes Principles", question: "Zoltan Dienes proposed that mathematical concepts should be experienced through varied concrete representations. This is the:", options: ["Perceptual Variability Principle (आकलनात्मक वैविध्य तत्त्व)", "Rote Drill Principle", "Abstract Proof Rule", "Formula First Principle"], answer: 0, explanation: "Dienes' Perceptual Variability Principle states that concepts should be explored across diverse sensory embodiments." },
        { subject: "Social Science", type: "History", tagText: "National Movement", question: "The historic 'Dandi March' (दांडी यात्रा) launched by Mahatma Gandhi in 1930 broke which British monopoly law?", options: ["Forest Law", "Salt Law (मीठाचा कायदा)", "Rowlatt Act", "Arms Act"], answer: 1, explanation: "The Salt Satyagraha began on 12 March 1930, culminating at Dandi where Gandhi made salt, defying the British salt tax." },
        { subject: "Social Science", type: "Geography", tagText: "Biosphere Reserves", question: "The Nilgiri Biosphere Reserve, the first biosphere reserve established in India (1986), is spread across which states?", options: ["Maharashtra and Gujarat", "Tamil Nadu, Kerala, and Karnataka (तामिळनाडू, केरळ व कर्नाटक)", "Assam and Meghalaya", "Odisha and Bengal"], answer: 1, explanation: "The Nilgiri Biosphere Reserve spans the Western Ghats junctions of Tamil Nadu, Kerala, and Karnataka." },
        { subject: "Social Science", type: "Civics", tagText: "Preamble", question: "Which of the following ideals was added to the Preamble of the Indian Constitution by the 42nd Amendment in 1976?", options: ["Liberty", "Secular (धर्मनिरपेक्ष)", "Republic", "Justice"], answer: 1, explanation: "The 42nd Constitutional Amendment Act of 1976 inserted 'Socialist', 'Secular', and 'Integrity' into the Preamble." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Primary Data", question: "Which method is most appropriate for middle school students collecting primary data on local municipal water supply issues?", options: ["Reading a history textbook chapter", "Conducting a door-to-door community survey questionnaire (स्थानिक सर्वेक्षण)", "Watching a fictional cinema film", "Copying from an encyclopedia"], answer: 1, explanation: "A field survey gathers fresh primary empirical data directly from community stakeholders." },
        { subject: "Language", type: "Grammar", tagText: "Conjunctions", question: "He worked hard ____ he might secure first rank.", options: ["so that", "lest", "because", "unless"], answer: 0, explanation: "'So that' expresses intended purpose followed by the modal 'might'." },
        { subject: "Language", type: "Vocab", tagText: "Synonym", question: "Synonym for 'Resilient':", options: ["Fragile", "Tough / Quick to recover (लवचिक/संकटातून सावरणारा)", "Rigid", "Feeble"], answer: 1, explanation: "'Resilient' means able to withstand or recover quickly from difficult conditions." },
        { subject: "Language", type: "Pedagogy", tagText: "Extensive Reading", question: "Extensive reading programs in middle school contribute significantly to:", options: ["Spelling drill tests", "Incidental vocabulary acquisition and overall reading fluency (नैसर्गिक शब्दसंग्रह व ओघवते वाचन)", "Handwriting calligraphy", "Memorizing grammar tables"], answer: 1, explanation: "Wide reading of authentic texts drives substantial incidental lexical acquisition and reading automaticity." },
        { subject: "Language", type: "Pedagogy", tagText: "Formative Assessment", question: "Providing descriptive feedback rather than mere letter grades on writing drafts:", options: ["Takes zero effort", "Directs learner attention to specific areas of syntactic clarity and textual coherence", "Discourages creative writers", "Violates examination rules"], answer: 1, explanation: "Descriptive formative feedback empowers writers with clear, actionable strategies to polish their drafts." }
    ],
    6: [
        { subject: "CDP", type: "PYQ", tagText: "Kohlberg", question: "In Kohlberg's theory, moral reasoning at the 'Social Contract and Individual Rights' stage (Stage 5) is grounded in:", options: ["Unquestioning obedience to adult rulers", "The understanding that laws are social agreements that can be democratically modified for common human good", "Physical punishment avoidance", "Personal pleasure seeking"], answer: 1, explanation: "Stage 5 views laws as flexible social contracts constructed democratically for mutual welfare and rights protection." },
        { subject: "CDP", type: "Concept", tagText: "Adolescent Identity", question: "James Marcia expanded Erikson's theory, defining 'Identity Achievement' (ओळख संपादन) as having undergone:", options: ["Crisis exploration and committed values choice (शोध व दृढ बांधिलकी)", "Neither crisis nor commitment", "Blind obedience to parents without exploration", "Permanent confusion"], answer: 0, explanation: "Identity Achievement occurs after exploring alternative pathways and committing consciously to clear goals and values." },
        { subject: "CDP", type: "IMP", tagText: "Peer Collaboration", question: "Peer tutoring and cooperative learning in middle school are effective because they capitalize on adolescents':", options: ["Desire to sit silently alone", "Social drive for peer interaction, shared dialogue, and co-construction of knowledge (सहकाऱ्यांशी संवाद व सहकार्य)", "Disinterest in studies", "Fear of punishment"], answer: 1, explanation: "Adolescents are primed for social connection; cooperative peer dialogue channels peer resonance into deeper academic learning." },
        { subject: "CDP", type: "Pedagogy", tagText: "Diagnostic Teaching", question: "If several students consistently make the same error in solving fraction equations, the teacher should:", options: ["Scold them loudly", "Conduct diagnostic analysis to uncover the underlying conceptual root cause and reteach with manipulatives (नैदानिक विश्लेषण व फेर-अध्यापन)", "Skip fractions in syllabus", "Fail all of them"], answer: 1, explanation: "Systematic errors highlight shared conceptual misconceptions requiring diagnostic inquiry and adapted pedagogical intervention." },
        { subject: "Science", type: "Physics", tagText: "Heat Transfer", question: "The transfer of heat from the Sun to the Earth through vast empty space occurs by:", options: ["Conduction", "Convection", "Radiation (प्रारण)", "Boiling"], answer: 2, explanation: "Radiation transfers thermal energy via electromagnetic infrared waves requiring no material medium." },
        { subject: "Science", type: "Chemistry", tagText: "Physical vs Chemical", question: "Which of the following is a chemical change (रासायनिक बदल)?", options: ["Melting of ice into water", "Dissolving sugar in water", "Burning of paper into ash (कागद जळून राख होणे)", "Tearing a sheet of paper"], answer: 2, explanation: "Burning paper forms new substances (ash, CO₂, water vapor) and is irreversible, making it a chemical change." },
        { subject: "Science", type: "Biology", tagText: "Human Circulatory", question: "In the human heart, which blood vessels carry oxygenated blood from the lungs into the left atrium?", options: ["Pulmonary artery", "Pulmonary veins (फुप्फुस शिरा)", "Vena cava", "Aorta"], answer: 1, explanation: "The pulmonary veins are unique veins carrying oxygen-rich blood from lungs back into the heart's left atrium." },
        { subject: "Science", type: "Pedagogy", tagText: "Models in Science", question: "Using 3D working models (like an eye model or volcano model) in middle school science helps because:", options: ["They replace textbooks forever", "They make abstract, hidden, or microscopic phenomena visually and spatially accessible", "They require no teacher explanation", "They cause noise"], answer: 1, explanation: "3D physical and digital models clarify spatial relationships and structural mechanisms that cannot be seen directly." },
        { subject: "Maths", type: "Algebra", tagText: "Identities", question: "If a + b = 9 and a² + b² = 41, what is the value of ab?", options: ["18", "20 (ab = २०)", "24", "40"], answer: 1, explanation: "(a + b)² = a² + b² + 2ab -> 9² = 41 + 2ab -> 81 - 41 = 2ab -> 2ab = 40 -> ab = 20." },
        { subject: "Maths", type: "Geometry", tagText: "Volume", question: "What is the volume of a right circular cylinder having a base radius of 7 cm and a height of 10 cm? (π = 22/7)", options: ["440 cu. cm", "1,540 cu. cm (१,५४० घन सेमी)", "2,200 cu. cm", "770 cu. cm"], answer: 1, explanation: "Volume = πr²h = (22/7) × 7 × 7 × 10 = 154 × 10 = 1,540 cubic centimeters." },
        { subject: "Maths", type: "Arithmetic", tagText: "Probability", question: "A fair standard six-sided die is rolled once. What is the probability of rolling a prime number?", options: ["1/6", "1/2 (१/२)", "1/3", "2/3"], answer: 1, explanation: "Prime numbers on a die: 2, 3, 5 (3 favorable outcomes). Total outcomes = 6. Probability = 3/6 = 1/2." },
        { subject: "Maths", type: "Pedagogy", tagText: "Mathematical Thinking", question: "The overarching goal of school mathematics education, as emphasized by NCF 2005, is to:", options: ["Train children to clear bank exams", "Mathematize the child's thinking processes (मुलाच्या विचारप्रक्रियेचे गणितीकरण करणे)", "Memorize all algebraic identities", "Fill exercise notebooks"], answer: 1, explanation: "NCF 2005 asserts that the core aim of math education is mathematization of thought: logical clarity, abstraction, and problem solving." },
        { subject: "Social Science", type: "History", tagText: "Revolt 1857", question: "The Revolt of 1857 officially broke out on 10 May 1857 in which cantonment town?", options: ["Barrackpore", "Meerut (मीरठ छावणी)", "Delhi", "Lucknow"], answer: 1, explanation: "The widespread sepoys' rebellion erupted on 10 May 1857 at Meerut cantonment, marching to Delhi the following day." },
        { subject: "Social Science", type: "Geography", tagText: "Rock Cycle", question: "Metamorphic rocks (रूपांतरित खडक) like Marble are formed by:", options: ["Cooling of volcanic lava", "Subjecting limestone to intense heat and pressure over long periods (तीव्र उष्णता व दाब)", "Accumulation of river sand", "Wind erosion"], answer: 1, explanation: "Marble is formed when sedimentary limestone undergoes metamorphic recrystallization under intense crustal heat and pressure." },
        { subject: "Social Science", type: "Civics", tagText: "Elections", question: "Universal Adult Suffrage (प्रौढ मताधिकार) guaranteed by the Indian Constitution ensures that:", options: ["Only educated taxpayers can vote", "Every citizen aged 18 and above has the right to one vote regardless of caste, gender, religion, or wealth", "Only property owners can vote", "Voting is reserved for men"], answer: 1, explanation: "Universal adult franchise grants one person, one vote, one value to all citizens aged 18+ without discrimination." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Historical Empathy", question: "Encouraging middle school students to write a fictional diary entry from the viewpoint of an ordinary weaver in 18th-century Bengal fosters:", options: ["Memorizing dates only", "Historical empathy and multi-perspective understanding of ordinary people's lives (ऐतिहासिक संवेदनशीलता)", "Blind nationalism", "Boredom"], answer: 1, explanation: "Perspective-taking diary writing cultivates historical empathy, illuminating how structural events impacted common human beings." },
        { subject: "Language", type: "Grammar", tagText: "Prepositions", question: "The student was congratulated ____ his outstanding success in the science Olympiad.", options: ["for", "on (on his success)", "at", "with"], answer: 1, explanation: "The standard prepositional collocation with 'congratulate' is 'congratulate someone ON something'." },
        { subject: "Language", type: "Vocab", tagText: "Antonym", question: "Choose the antonym of 'Ambiguous':", options: ["Clear / Lucid (स्पष्ट/सुबोध)", "Vague", "Obscure", "Doubtful"], answer: 0, explanation: "'Ambiguous' means open to more than one interpretation; its antonym is 'Clear' or 'Unambiguous'." },
        { subject: "Language", type: "Pedagogy", tagText: "Cooperative Learning", question: "Literature Circles in upper primary language classrooms promote:", options: ["Teacher lectures the whole hour", "Student-led collaborative discussions on shared reading texts taking different roles (discussion leader, word wizard, summarizer)", "Competitive silent exams", "Chanting word spellings"], answer: 1, explanation: "Literature circles engage students in peer-led discussion roles, building reader agency and deep text comprehension." },
        { subject: "Language", type: "Pedagogy", tagText: "Diagnostic Test", question: "Diagnostic language assessment aims primarily at:", options: ["Ranking children from 1 to 50", "Identifying specific persistent linguistic gaps to plan remedial learning modules (नेमक्या भाषिक अडचणी शोधणे)", "Awarding annual scholarships", "Determining school fees"], answer: 1, explanation: "Diagnostic testing diagnoses specific phonetic, grammatical, or reading hurdles so customized remediation can follow." }
    ],
    7: [
        { subject: "CDP", type: "PYQ", tagText: "Vygotsky", question: "Lev Vygotsky argued that higher psychological functions (like voluntary attention and logical memory) originate from:", options: ["Inborn genetic reflexes only", "Social relations and collaborative interactions between individuals (सामाजिक आंतरक्रिया)", "Physical nutrition alone", "Rote practice"], answer: 1, explanation: "Vygotsky's cultural-historical theory stated that all higher functions appear twice: first socially, then internally." },
        { subject: "CDP", type: "Concept", tagText: "Piaget", question: "According to Piaget, the mental mechanism that drives cognitive transition from one stage of thought to the next is:", options: ["Conditioning", "Equilibration (संतुलनीकरण)", "Passive absorption", "Drill and practice"], answer: 1, explanation: "Equilibration is the dynamic self-regulatory drive reconciling cognitive disequilibrium into higher-level mental schemas." },
        { subject: "CDP", type: "IMP", tagText: "Adolescent Cognition", question: "Adolescents become capable of 'Propositional Logic' (प्रतिज्ञप्ती तर्क), meaning they can evaluate:", options: ["Only concrete objects they can touch", "The logical validity of verbal statements without needing concrete real-world objects", "Nothing abstract", "Only simple pictures"], answer: 1, explanation: "Propositional logic evaluates the internal logical consistency of hypothetical statements regardless of concrete reality." },
        { subject: "CDP", type: "Pedagogy", tagText: "Rubrics", question: "A primary benefit of sharing evaluation rubrics with middle school students prior to an assignment is that it:", options: ["Gives them the answers to copy", "Makes performance expectations transparent and enables proactive self-regulation and self-monitoring", "Prevents grading", "Removes homework"], answer: 1, explanation: "Pre-shared rubrics clarify quality benchmarks, empowering students to regulate and self-assess their own work." },
        { subject: "Science", type: "Physics", tagText: "Optics", question: "Which type of mirror is utilized by dentists to examine enlarged images of patients' teeth?", options: ["Plane mirror", "Concave mirror (अंतर्गोल आरसा)", "Convex mirror", "Cylindrical mirror"], answer: 1, explanation: "When an object is placed close to a concave mirror (within focal length), it produces an upright, magnified virtual image." },
        { subject: "Science", type: "Chemistry", tagText: "Synthetic Fibres", question: "Which synthetic fibre, synthesized from coal, water, and air without plant or animal raw materials, was the first fully synthetic fibre?", options: ["Rayon", "Nylon (नायलॉन)", "Polyester", "Acrylic"], answer: 1, explanation: "Nylon was invented in 1931 as the first 100% synthetic polymer fibre, renowned for high tensile strength and elasticity." },
        { subject: "Science", type: "Biology", tagText: "Genetics", question: "In human genetics, which pair of sex chromosomes determines that a newborn baby will be genetically female?", options: ["XY", "XX (XX गुणसूत्रे)", "YY", "XO"], answer: 1, explanation: "Females carry two X chromosomes (XX), whereas males possess one X and one Y chromosome (XY)." },
        { subject: "Science", type: "Pedagogy", tagText: "Experimentation", question: "When middle school science students formulate a hypothesis, they are engaging in:", options: ["Memorizing historical dates", "Proposing a testable, tentative explanation for an observed phenomenon (पडताळणीयोग्य तात्पुरते स्पष्टीकरण)", "Writing a final lab conclusion", "Making random wild guesses"], answer: 1, explanation: "A hypothesis is an informed, testable scientific prediction formulated prior to controlled experimentation." },
        { subject: "Maths", type: "Algebra", tagText: "Linear Inequalities", question: "Solve for x: 4x - 5 < 15, where x is a positive integer. What is the solution set for x?", options: ["{1, 2, 3, 4} ({१, २, ३, ४})", "{1, 2, 3, 4, 5}", "{0, 1, 2, 3}", "{5, 6, 7}"], answer: 0, explanation: "4x < 15 + 5 -> 4x < 20 -> x < 5. For positive integers (x > 0), x can be 1, 2, 3, 4." },
        { subject: "Maths", type: "Geometry", tagText: "Circles", question: "The ratio of the circumference of any circle to its diameter is always a constant mathematical value known as:", options: ["Euler's number e", "Pi (π - पाय)", "Golden ratio φ", "Square root 2"], answer: 1, explanation: "By definition, the constant ratio of circumference (C) to diameter (d) of any circle is Pi (π ≈ 3.14159)." },
        { subject: "Maths", type: "Statistics", tagText: "Central Tendency", question: "Which measure of central tendency represents the most frequently occurring value in a data set?", options: ["Mean", "Median", "Mode (बहुलक)", "Range"], answer: 2, explanation: "Mode is the observation that appears with maximum frequency in a given distribution." },
        { subject: "Maths", type: "Pedagogy", tagText: "Visualization", question: "Using dynamic geometry software (like GeoGebra) in middle school geometry lessons primarily assists learners in:", options: ["Playing video games", "Dynamically visualizing, manipulating, and verifying geometric properties and theorems interactively", "Printing static worksheets", "Replacing mental math"], answer: 1, explanation: "Dynamic geometry software allows students to drag vertices and explore invariant properties in real-time." },
        { subject: "Social Science", type: "History", tagText: "Social Reform", question: "Who founded the 'Brahmo Samaj' (ब्राह्मो समाज) in Kolkata in 1828 to combat sati and idol worship?", options: ["Swami Vivekananda", "Raja Ram Mohan Roy (राजाराम मोहन रॉय)", "Ishwar Chandra Vidyasagar", "Dayananda Saraswati"], answer: 1, explanation: "Raja Ram Mohan Roy established Brahmo Samaj, leading the campaign to ban Sati (enacted in 1829)." },
        { subject: "Social Science", type: "Geography", tagText: "Volcanoes", question: "The 'Ring of Fire' (अग्निकंकण), known for frequent earthquakes and active volcanoes, encircles which ocean basin?", options: ["Atlantic Ocean", "Pacific Ocean (पॅसिफिक महासागर)", "Indian Ocean", "Arctic Ocean"], answer: 1, explanation: "The Pacific Ring of Fire is a major tectonic boundary home to 75% of the planet's active volcanoes and 90% of earthquakes." },
        { subject: "Social Science", type: "Civics", tagText: "Right to Information", question: "The Right to Information (RTI) Act in India was enacted by Parliament in which year to ensure transparency?", options: ["2000", "2005 (२००५)", "2010", "2015"], answer: 1, explanation: "The landmark RTI Act was passed in 2005, guaranteeing citizen access to records of public authorities." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Critical Thinking", question: "Asking students to compare British colonial accounts of the 1857 rebellion with Indian vernacular accounts develops:", options: ["Confusion and failure", "Critical historical thinking, bias detection, and historiographical awareness (ऐतिहासिक बहुदृष्टिकोन)", "Disregard for books", "Blind memorization of dates"], answer: 1, explanation: "Juxtaposing multiple historical sources exposes perspective bias, training pupils in analytical historiography." },
        { subject: "Language", type: "Grammar", tagText: "Conditionals", question: "If I had known about the workshop, I ____ attended it.", options: ["will have", "would have (third conditional)", "would", "had"], answer: 1, explanation: "Third conditional (hypothetical past): 'If + had + V3, would have + V3'." },
        { subject: "Language", type: "Vocab", tagText: "Idiom", question: "What does the idiom 'To see eye to eye' mean?", options: ["To look into a mirror", "To agree fully with someone (पूर्ण सहमती असणे)", "To fight face to face", "To become blind"], answer: 1, explanation: "'To see eye to eye' means to have identical views or agree completely on a topic." },
        { subject: "Language", type: "Pedagogy", tagText: "Authentic Materials", question: "Using authentic newspaper editorials in Grade 8 English classes helps adolescents to:", options: ["Practice simple spelling only", "Analyze rhetorical arguments, persuasive strategies, and evaluate claims against evidence", "Avoid reading literature", "Memorize dates"], answer: 1, explanation: "Editorials expose adolescents to authentic persuasive argumentation, rhetorical discourse, and evidence appraisal." },
        { subject: "Language", type: "Pedagogy", tagText: "Peer Feedback", question: "In a collaborative writing workshop, peer review is most effective when students:", options: ["Give only harsh negative insults", "Use structured guidelines to offer constructive suggestions on content, clarity, and organization", "Rewrite the friend's entire essay", "Assign final exam grades"], answer: 1, explanation: "Structured peer review protocols focus student feedback constructively on substantive communication quality." }
    ],
    8: [
        { subject: "CDP", type: "PYQ", tagText: "Constructivism", question: "According to constructivist theories of learning, learners are best described as:", options: ["Passive recording devices of textbook sentences", "Active meaning-makers who interpret new experiences through their existing mental frameworks (ज्ञानाचे सक्रिय निर्माते)", "Tabula Rasa blank slates", "Machines conditioned by punishment"], answer: 1, explanation: "Constructivism views learners as agentic constructors who assimilate and adapt concepts through active engagement." },
        { subject: "CDP", type: "Concept", tagText: "Metacognition", question: "Metacognitive knowledge encompasses three main variables: Person variables, Task variables, and:", options: ["Reward variables", "Strategy variables (व्यूहरचना घटक - कोणती पद्धत कधी वापरावी)", "Punishment variables", "Physical height variables"], answer: 1, explanation: "Flavell's metacognitive framework includes knowledge of Person (self as learner), Task (nature of demands), and Strategy." },
        { subject: "CDP", type: "IMP", tagText: "Emotional Intelligence", question: "Daniel Goleman highlighted that in adolescent academic and life success, Emotional Intelligence (EQ) is often:", options: ["Irrelevant compared to pure IQ", "As significant as or more significant than conventional cognitive IQ in navigating relationships and resilience", "Only useful for singing", "Negative for study"], answer: 1, explanation: "Goleman argued that self-awareness, impulse control, empathy, and social skills (EQ) are vital predictors of life success." },
        { subject: "CDP", type: "Pedagogy", tagText: "Inclusive Setup", question: "In an inclusive middle school, physical and architectural barriers for students with orthopaedic challenges can be removed by providing:", options: ["Ramps, accessible toilets, and wide doorways (रॅम्प्स व सुलभ मार्ग)", "Elevators only for teachers", "Home schooling only", "Segregated basement classes"], answer: 0, explanation: "Universal accessibility entails barrier-free physical infrastructure like ramps, handrails, and adaptive desks." },
        { subject: "Science", type: "Physics", tagText: "Pressure & Liquid", question: "In a liquid container at rest, the hydrostatic pressure exerted by the liquid at a given depth:", options: ["Acts only downwards", "Acts equally in all directions and increases with depth (सर्व दिशांनी समान व खोलीनुसार वाढते)", "Decreases with depth", "Is zero at the bottom"], answer: 1, explanation: "Liquid pressure acts equally in all directions at the same depth and increases linearly with liquid column height." },
        { subject: "Science", type: "Chemistry", tagText: "Periodic Table", question: "In the modern periodic table developed by Henry Moseley, elements are systematically arranged in order of increasing:", options: ["Atomic mass", "Atomic number (अणुअंक - प्रोटॉन्सची संख्या)", "Density", "Number of neutrons"], answer: 1, explanation: "The modern periodic table organizes chemical elements by increasing atomic number (Z, number of nuclear protons)." },
        { subject: "Science", type: "Biology", tagText: "Microbiology", question: "Penicillin, the first miraculous medical antibiotic, was discovered from a mould fungus in 1928 by:", options: ["Louis Pasteur", "Alexander Fleming (अलेक्झांडर फ्लेमिंग)", "Edward Jenner", "Robert Koch"], answer: 1, explanation: "Sir Alexander Fleming discovered the antibacterial properties of Penicillium notatum mould in 1928." },
        { subject: "Science", type: "Pedagogy", tagText: "Concept Mapping", question: "Having middle school students construct a Concept Map connecting photosynthesis, respiration, and the carbon cycle primarily supports:", options: ["Rote memorization of Latin names", "Relational understanding and visual synthesis of interconnected biological concepts (संकल्पनात्मक आंतरसंबंध जोडणे)", "Speed writing", "Drawing art grades"], answer: 1, explanation: "Concept maps illustrate hierarchical interconnections and cross-links between abstract science concepts." },
        { subject: "Maths", type: "Arithmetic", tagText: "Simple vs Compound", question: "On a sum of ₹10,000 for 2 years at 10% per annum, what is the difference between Compound Interest and Simple Interest?", options: ["₹50", "₹100 (१०० रुपये)", "₹150", "₹200"], answer: 1, explanation: "Difference for 2 years = P(r/100)² = 10000 × (10/100)² = 10000 × (1/100) = ₹100." },
        { subject: "Maths", type: "Geometry", tagText: "Quadrilaterals", question: "The diagonals of which quadrilateral bisect each other perpendicularly at right angles and are equal in length?", options: ["Rhombus", "Rectangle", "Square (चौरस)", "Parallelogram"], answer: 2, explanation: "A square has diagonals that are both equal in length and perpendicular bisectors of each other." },
        { subject: "Maths", type: "Algebra", tagText: "Factorisation", question: "Factorise: 4a² - 9b².", options: ["(2a - 3b)(2a + 3b)", "(4a - 9b)(4a + 9b)", "(2a - 3b)²", "(2a + 3b)²"], answer: 0, explanation: "Using the difference of squares identity x² - y² = (x - y)(x + y): (2a)² - (3b)² = (2a - 3b)(2a + 3b)." },
        { subject: "Maths", type: "Pedagogy", tagText: "Mathematical Proof", question: "Why is 'proof by contradiction' (व्याघात पद्धतीने सिद्धता) important in secondary mathematics?", options: ["It confuses children purposefully", "It teaches rigorous deductive reasoning by assuming the negation of a proposition and deriving an impossibility", "It is only a guessing trick", "It replaces numbers"], answer: 1, explanation: "Proof by contradiction (e.g., proving √2 is irrational) demonstrates logical rigor by reducing hypotheses to absurdities." },
        { subject: "Social Science", type: "History", tagText: "Ancient India", question: "Which ancient university in Bihar was a renowned international center of Buddhist learning, visited by Xuanzang (Hiuen Tsang)?", options: ["Nalanda University (नालंदा विद्यापीठ)", "Taxila", "Vikramashila", "Vallabhi"], answer: 0, explanation: "Nalanda Mahavihara was founded during the Gupta period, attracting thousands of international scholars." },
        { subject: "Social Science", type: "Geography", tagText: "Hydrosphere", question: "The famous warm ocean current that flows northeast along the east coast of North America into the Atlantic is the:", options: ["Canary Current", "Gulf Stream (गल्फ प्रवाह)", "Labrador Current", "Benguela Current"], answer: 1, explanation: "The Gulf Stream is a swift warm ocean current moderating Western Europe's climate." },
        { subject: "Social Science", type: "Civics", tagText: "Fundamental Rights", question: "Which Fundamental Right under Article 21 was judicially expanded to include the 'Right to Privacy'?", options: ["Right to Equality", "Right to Life and Personal Liberty (जीवनाचा व वैयक्तिक स्वातंत्र्याचा हक्क)", "Right against Exploitation", "Right to Freedom of Religion"], answer: 1, explanation: "The Supreme Court (Puttaswamy case) held that Right to Privacy is intrinsic to Right to Life under Article 21." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Case Studies", question: "Using case studies of tribal displaced communities due to major dam projects in social science class encourages:", options: ["One-sided hatred", "Critical examination of development trade-offs, human displacement, and social justice (सामाजिक न्यायाचा सर्वांगीण विचार)", "Disregard for development", "Only rote learning"], answer: 1, explanation: "Case studies illuminate competing socio-economic interests, fostering nuanced policy critique and human rights empathy." },
        { subject: "Language", type: "Grammar", tagText: "Tenses", question: "Identify the tense: 'By the time the bell rang, the students had submitted their answer sheets.'", options: ["Simple Past", "Past Perfect (पूर्ण भूतकाळ)", "Past Continuous", "Present Perfect"], answer: 1, explanation: "'had + V3 (submitted)' indicates an event completed prior to another past milestone (rang), making it Past Perfect." },
        { subject: "Language", type: "Vocab", tagText: "Synonym", question: "Synonym for 'Pragmatic':", options: ["Idealistic", "Practical / Realistic (व्यावहारिक)", "Fanciful", "Careless"], answer: 1, explanation: "'Pragmatic' means dealing with things sensibly and realistically based on practical considerations." },
        { subject: "Language", type: "Pedagogy", tagText: "Critical Literacy", question: "When teaching advertising texts in English class, asking 'Who created this message and what product are they persuading us to buy?' cultivates:", options: ["Greed for shopping", "Media literacy and critical deconstruction of persuasive rhetoric (माध्यम साक्षरता व विश्लेषणात्मक विचार)", "Spelling drill mastery", "Passive consumerism"], answer: 1, explanation: "Media literacy empowers adolescents to analyze targeted marketing appeals, persuasive bias, and implied consumer values." },
        { subject: "Language", type: "Pedagogy", tagText: "Assessment", question: "A scoring guide with specific performance criteria on a 4-point scale used to evaluate oral presentations is a:", options: ["Rubric (मूल्यमापन रुब्रिक)", "Textbook index", "Syllabus checklist", "Time table"], answer: 0, explanation: "A scoring rubric defines descriptive standards across quality dimensions, enabling objective holistic assessment." }
    ],
    9: [
        { subject: "CDP", type: "PYQ", tagText: "Piaget vs Vygotsky", question: "A fundamental difference between Jean Piaget and Lev Vygotsky lies in their view of:", options: ["Whether children should attend school", "The role of language: Piaget saw it as reflecting thought, whereas Vygotsky saw it as actively shaping thought (भाषेची विकासातील भूमिका)", "Whether memory exists", "Whether parents matter"], answer: 1, explanation: "Piaget viewed egocentric speech as a symptom of cognitive immaturity; Vygotsky viewed it as a vital tool shaping self-directed thought." },
        { subject: "CDP", type: "Concept", tagText: "Motivation", question: "Students who adopt a 'Growth Mindset' (Carol Dweck) believe that intelligence is:", options: ["A fixed, unchangeable trait determined at birth", "Malleable and can be developed through dedication, strategic effort, and learning from mistakes (प्रयत्नांनी वाढवणारी क्षमता)", "A lottery ticket", "Only present in teachers"], answer: 1, explanation: "A growth mindset posits that intellectual ability can be cultivated through effort, deliberate practice, and persistence." },
        { subject: "CDP", type: "IMP", tagText: "Gender Socialization", question: "In middle school, teachers can actively counteract gender stereotyping by:", options: ["Assigning boys to carry heavy desks and girls to sweep floors", "Presenting gender-neutral role models and encouraging all genders in science, mathematics, and leadership roles (समान संधी व पूर्वग्रहमुक्त वातावरण)", "Segregating seating by gender permanently", "Ignoring girls when they raise hands"], answer: 1, explanation: "Promoting non-traditional role models and equal cross-gender participation dismantles limiting gender stereotypes." },
        { subject: "CDP", type: "Pedagogy", tagText: "Differentiated Instruction", question: "Differentiated instruction in a mixed-ability Grade 8 classroom involves:", options: ["Teaching to the top 5 students only", "Adapting content, learning processes, and product expectations according to diverse learner profiles and readiness levels (वैविध्यपूर्ण गरजांनुसार अध्यापनात लवचिकता)", "Giving identical worksheets to all", "Failing students who work slowly"], answer: 1, explanation: "Differentiation customizes curricular pace, representation modalities, and task complexity to match individual learner readiness." },
        { subject: "Science", type: "Physics", tagText: "Refraction", question: "When a pencil is partially immersed in a glass of water, it appears bent at the water surface due to:", options: ["Reflection of light", "Refraction of light (प्रकाशाचे अपवर्तन)", "Total internal reflection", "Dispersion"], answer: 1, explanation: "Refraction (bending of light) occurs because light travels at different speeds in air and optical water media." },
        { subject: "Science", type: "Chemistry", tagText: "Acids & Metals", question: "When dilute hydrochloric acid reacts with zinc granules, which flammable gas is liberated with a pop sound?", options: ["Oxygen", "Hydrogen gas (हायड्रोजन वायू - H₂)", "Carbon dioxide", "Nitrogen"], answer: 1, explanation: "Zn + 2HCl -> ZnCl₂ + H₂↑. Hydrogen gas burns with a characteristic pop sound when a burning splinter is brought near." },
        { subject: "Science", type: "Biology", tagText: "Ecosystem", question: "In an ecological food chain (Grass -> Grasshopper -> Frog -> Snake -> Eagle), the Snake occupies which trophic level?", options: ["Primary consumer", "Secondary consumer", "Tertiary consumer (तृतीयक ग्राहक)", "Decomposer"], answer: 2, explanation: "Grass (producer) -> Grasshopper (primary) -> Frog (secondary) -> Snake (tertiary consumer)." },
        { subject: "Science", type: "Pedagogy", tagText: "Open Inquiry", question: "Which of the following science classroom activities provides the highest level of student autonomy?", options: ["Following step-by-step recipe instructions in a lab manual", "Open-inquiry investigation where students formulate their own research questions, design tests, and draw conclusions (मुक्त संशोधन प्रकल्प)", "Watching a YouTube science video", "Copying formulas"], answer: 1, explanation: "Open inquiry maximizes student agency by placing question formulation, methodology design, and data interpretation in students' hands." },
        { subject: "Maths", type: "Algebra", tagText: "Factorisation", question: "What are the roots of the quadratic equation: x² - 9x + 20 = 0?", options: ["x = 4 and x = 5 (x = ४ व x = ५)", "x = -4 and x = -5", "x = 2 and x = 10", "x = 1 and x = 20"], answer: 0, explanation: "(x - 4)(x - 5) = 0 -> x = 4 or x = 5." },
        { subject: "Maths", type: "Geometry", tagText: "Parallel Lines", question: "When two parallel lines are intersected by a transversal, the interior angles on the same side of the transversal are:", options: ["Equal", "Complementary (add up to 90°)", "Supplementary (add up to 180° - आंतरकोन पूरक असतात)", "Always right angles"], answer: 2, explanation: "Consecutive interior angles on the same side of a transversal intersecting parallel lines sum to 180° (supplementary)." },
        { subject: "Maths", type: "Arithmetic", tagText: "Speed & Time", question: "A train 150 meters long is traveling at a speed of 54 km/h. How many seconds will it take to pass a stationary telegraph post?", options: ["8 seconds", "10 seconds (१० सेकंद)", "12 seconds", "15 seconds"], answer: 1, explanation: "Speed = 54 × (5/18) = 15 m/s. Time to cross post = Distance ÷ Speed = 150 ÷ 15 = 10 seconds." },
        { subject: "Maths", type: "Pedagogy", tagText: "Generalization", question: "When students discover that 1+3=4, 1+3+5=9, and 1+3+5+7=16, and conclude that the sum of the first n odd numbers is n², they are demonstrating:", options: ["Deductive proof", "Mathematical induction and algebraic generalization (गणितीय विगमन व सामान्यीकरण)", "Rote computation", "Geometric theorem"], answer: 1, explanation: "Inductive mathematical generalization identifies structural patterns across numeric instances to formulate general algebraic laws." },
        { subject: "Social Science", type: "History", tagText: "Medieval India", question: "Which Delhi Sultan introduced market control regulations and price fixing for grain, cloth, and horses?", options: ["Iltutmish", "Alauddin Khalji (अल्लाउद्दीन खिलजी)", "Muhammad bin Tughluq", "Balban"], answer: 1, explanation: "Alauddin Khalji enacted strict market price regulations and established supervised grain markets (Mandi) in Delhi." },
        { subject: "Social Science", type: "Geography", tagText: "Tides", question: "Spring tides (उधाणाची भरती) with the highest tidal range occur when:", options: ["The Moon is in its first quarter", "The Sun, the Moon, and the Earth are in a straight line (Full Moon and New Moon)", "The Moon and Sun are at right angles", "In winter only"], answer: 1, explanation: "During New Moon and Full Moon, the solar and lunar gravitational pulls align, generating maximum spring tides." },
        { subject: "Social Science", type: "Civics", tagText: "Directive Principles", question: "The Directive Principles of State Policy (मार्गदर्शक तत्त्वे) in Part IV of the Indian Constitution were borrowed from which country's constitution?", options: ["USA", "Ireland (आयर्लंड)", "USSR", "Great Britain"], answer: 1, explanation: "The framers of the Indian Constitution drew inspiration for the Directive Principles of State Policy from the Irish Constitution." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Community Resources", question: "Inviting a local village potter, a handloom weaver, and an elected panchayat member into the classroom serves as an authentic:", options: ["Wasted school day", "Integration of community knowledge and live human resources into social science learning (स्थानिक सामाजिक संसाधनांचा वापर)", "Disruption of timetable", "Mock test"], answer: 1, explanation: "Community resource persons bridge lived social realities and local economic traditions directly into academic inquiry." },
        { subject: "Language", type: "Grammar", tagText: "Relative Pronouns", question: "The painting, ____ was gifted by my grandmother, is hanging on the living room wall.", options: ["who", "which / that (which)", "whom", "whose"], answer: 1, explanation: "'Which' is the non-restrictive relative pronoun used to refer to inanimate objects (the painting)." },
        { subject: "Language", type: "Vocab", tagText: "Antonym", question: "Choose the antonym of 'Complacent':", options: ["Smug", "Concerned / Dissatisfied / Vigilant (दक्ष/सावध)", "Content", "Pleased"], answer: 1, explanation: "'Complacent' means smugly self-satisfied without concern for potential danger; its antonym is 'Vigilant' or 'Concerned'." },
        { subject: "Language", type: "Pedagogy", tagText: "Critical Literacy", question: "When middle school students compare news headlines from three different television channels covering the same political event, they learn to:", options: ["Distrust all human communication", "Recognize media framing, editorial perspective, and linguistic emphasis (माध्यम दृष्टीकोन ओळखणे)", "Memorize television scripts", "Avoid reading newspapers"], answer: 1, explanation: "Comparative media analysis fosters critical awareness of editorial framing, linguistic tone, and narrative construction." },
        { subject: "Language", type: "Pedagogy", tagText: "Assessment for Learning", question: "Assessment for Learning (AfL) in English is characterized by:", options: ["Assigning annual letter grades", "Ongoing informal observations and dialogic feedback to calibrate instructional support (अध्ययनासाठीचे सातत्यपूर्ण मूल्यमापन)", "Publishing class rank list on notice boards", "Administering surprise penalty quizzes"], answer: 1, explanation: "AfL is ongoing, diagnostic, and formative, providing descriptive feedback to scaffold student mastery." }
    ],
    10: [
        { subject: "CDP", type: "PYQ", tagText: "Gardner", question: "According to Howard Gardner, a psychologist or counselor who displays deep sensitivity to the motivations, moods, and feelings of others possesses high:", options: ["Intrapersonal Intelligence", "Interpersonal Intelligence (आंतरवैयक्तिक बुद्धिमत्ता)", "Naturalistic Intelligence", "Spatial Intelligence"], answer: 1, explanation: "Interpersonal intelligence enables empathetic perception and effective interaction with other human beings." },
        { subject: "CDP", type: "Concept", tagText: "Piaget", question: "In Piaget's cognitive theory, when a teenager realizes that their previous explanation for a physics problem no longer works and modifies their cognitive schema, this process is:", options: ["Assimilation", "Accommodation (समायोजन / समंजन)", "Centration", "Conservation"], answer: 1, explanation: "Accommodation occurs when internal cognitive schemas are modified or restructured in response to novel counter-evidence." },
        { subject: "CDP", type: "IMP", tagText: "Inclusive Ed", question: "The fundamental philosophy of inclusive education in middle schools demands that:", options: ["Children with special needs adapt to rigid unchanged school policies", "The school curriculum, physical infrastructure, and pedagogies adapt flexibly to welcome all diverse learners", "Special children sit in separate corridors", "Only high-performing children receive advanced materials"], answer: 1, explanation: "Inclusion shifts the burden of adaptation from the child onto the educational system and its learning environments." },
        { subject: "CDP", type: "Pedagogy", tagText: "Scaffolding", question: "Which of the following is a clear example of effective 'Scaffolding' provided by an upper primary teacher?", options: ["Solving all math problems on the board for students to copy word for word", "Providing half-solved exemplars, guiding questions, and graphic prompts that fade as competence grows (मार्गदर्शक आधाराची चौकट)", "Leaving students completely unassisted without any resources", "Giving failing marks immediately on first drafts"], answer: 1, explanation: "Scaffolding offers temporary structured guidance within the ZPD, gradually fading as learners develop autonomous mastery." },
        { subject: "Science", type: "Physics", tagText: "Motion Laws", question: "Which law of motion explains why passengers lurch forward when a moving bus suddenly applies emergency brakes?", options: ["Newton's First Law of Motion (Law of Inertia - जडत्वाचा नियम)", "Newton's Second Law of Motion", "Newton's Third Law of Motion", "Law of Universal Gravitation"], answer: 0, explanation: "By Newton's First Law (Inertia of Motion), the passengers' upper bodies continue moving forward when the bus decelerates." },
        { subject: "Science", type: "Chemistry", tagText: "Acids, Bases, Salts", question: "The chemical reaction between an acid and a base yielding a salt and water along with heat is known as:", options: ["Oxidation reaction", "Neutralization reaction (उदासीनीकरण अभिक्रिया)", "Combustion reaction", "Precipitation reaction"], answer: 1, explanation: "Acid + Base -> Salt + Water + Heat is a classic neutralization reaction (e.g., HCl + NaOH -> NaCl + H₂O)." },
        { subject: "Science", type: "Biology", tagText: "Respiration", question: "During vigorous heavy physical exercise, human muscle cells break down glucose anaerobically, producing:", options: ["Carbon dioxide and water only", "Lactic acid causing muscle cramps (लॅक्टिक आम्ल)", "Alcohol and methane", "Oxygen"], answer: 1, explanation: "Temporary oxygen debt leads to anaerobic respiration in muscle fibers, accumulating lactic acid and causing fatigue." },
        { subject: "Science", type: "Pedagogy", tagText: "Formative Assessment", question: "Exit tickets where middle school students write one new scientific insight and one unresolved question at the end of a lesson serve as:", options: ["Formal grading tests", "Formative assessment to gauge real-time student comprehension and guide next-day instruction (आकारिक मूल्यमापन)", "Disciplinary homework penalties", "Attendance logs"], answer: 1, explanation: "Exit tickets provide quick diagnostic feedback on student comprehension to inform instructional adjustments." },
        { subject: "Maths", type: "Algebra", tagText: "Simultaneous Equations", question: "Solve the system of equations: x + y = 14 and x - y = 4. What is the value of x and y?", options: ["x = 9, y = 5 (x = ९, y = ५)", "x = 10, y = 4", "x = 8, y = 6", "x = 11, y = 3"], answer: 0, explanation: "Adding equations: 2x = 18 -> x = 9. Substituting x = 9 into first equation: 9 + y = 14 -> y = 5." },
        { subject: "Maths", type: "Geometry", tagText: "Angles in Polygon", question: "How many sides does a regular polygon have if each of its interior angles measures 120°?", options: ["5 sides", "6 sides (षटकोन - ६ बाजू)", "8 sides", "10 sides"], answer: 1, explanation: "Exterior angle = 180° - 120° = 60°. Number of sides n = 360° ÷ exterior angle = 360° ÷ 60° = 6 sides." },
        { subject: "Maths", type: "Arithmetic", tagText: "Profit and Loss", question: "A trader buys a bicycle for ₹2,400 and sells it for ₹3,000. What is his percentage profit?", options: ["20%", "25% (२५% नफा)", "30%", "15%"], answer: 1, explanation: "Profit = 3000 - 2400 = ₹600. Percentage profit = (Profit ÷ Cost Price) × 100 = (600 ÷ 2400) × 100 = 25%." },
        { subject: "Maths", type: "Pedagogy", tagText: "Error Analysis", question: "When a Grade 7 student adds fractions as 2/3 + 3/5 = 5/8 (adding numerators and denominators directly), the error reflects:", options: ["Carelessness only", "Overgeneralization of whole-number addition rules to fractions (अपूर्णांकांच्या संकल्पनेचा अभाव)", "Inability to learn math", "Disobedience"], answer: 1, explanation: "The student misapplies additive whole-number schemas directly across fractions, lacking the concept of common units." },
        { subject: "Social Science", type: "History", tagText: "Chola Empire", question: "The magnificent Brihadisvara Temple (बृहदीश्वर मंदिर) at Thanjavur, an architectural masterpiece of Dravidian style, was built by which Chola emperor?", options: ["Rajaraja I (राजाराम/राजाराम प्रथम - राजाराज १)", "Rajendra I", "Parantaka I", "Kulothunga I"], answer: 0, explanation: "Rajaraja Chola I built the grand Brihadisvara Temple dedicated to Lord Shiva at Thanjavur in 1010 CE." },
        { subject: "Social Science", type: "Geography", tagText: "Solar System", question: "The imaginary line dividing day and night across the Earth's surface as it rotates on its axis is termed the:", options: ["Equator", "Circle of Illumination (प्रकाशन वृत्त)", "Prime Meridian", "Tropic of Cancer"], answer: 1, explanation: "The Circle of Illumination is the great circle that divides the daylight hemisphere from the dark nocturnal hemisphere." },
        { subject: "Social Science", type: "Civics", tagText: "Marginalization", question: "In the context of Indian society, marginalized groups are those who are:", options: ["Extremely wealthy and powerful", "Pushed to the margins of society and denied equal access to resources, opportunities, and social prestige (वंचित व परिघावरील घटक)", "Exempt from laws", "Always in majority"], answer: 1, explanation: "Marginalized groups (Adivasis, Dalits, minorities) experience systemic exclusion from social, political, and economic power." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Interdisciplinary", question: "Connecting the historical study of the Industrial Revolution with modern geographic pollution data and civics labor rights issues is an example of:", options: ["Confusion of syllabus", "An interdisciplinary pedagogical approach (आंतरविद्याशाखीय दृष्टिकोन)", "Wasted teaching time", "Violating textbooks"], answer: 1, explanation: "Interdisciplinary pedagogy bridges history, geography, and political economy into a coherent, holistic analytical framework." },
        { subject: "Language", type: "Grammar", tagText: "Modals", question: "The sky is overcast with dark rain clouds; it ____ rain this evening.", options: ["may / might (may - शक्यता)", "must", "should", "ought to"], answer: 0, explanation: "'May' expresses strong factual possibility based on visible meteorological evidence (dark clouds)." },
        { subject: "Language", type: "Vocab", tagText: "Synonym", question: "Synonym for 'Impeccable':", options: ["Flawed", "Flawless / Perfect (निर्दोष / परिपूर्ण)", "Careless", "Weak"], answer: 1, explanation: "'Impeccable' means in accordance with the highest standards; faultless, flawless, or perfect." },
        { subject: "Language", type: "Pedagogy", tagText: "Writing Workshop", question: "During the 'Editing' stage of a middle school writing workshop, the primary focus is on:", options: ["Generating initial creative ideas", "Polishing mechanical accuracy: spelling, grammar, punctuation, and capitalization (शुद्धलेखन व व्याकरण सुधारणा)", "Deleting the whole story", "Drawing illustrations"], answer: 1, explanation: "Editing focuses on surface-level correctness: mechanics, orthography, syntax, and punctuation before publication." },
        { subject: "Language", type: "Pedagogy", tagText: "Communicative Competence", question: "Dell Hymes proposed 'Communicative Competence' to emphasize that knowing a language entails:", options: ["Only memorizing abstract grammar rules", "Knowing when to speak, when not to speak, what to talk about, with whom, when, where, and in what manner (भाषिक सामाजिक संवाद कौशल्य)", "Having zero accent", "Passing written tests only"], answer: 1, explanation: "Communicative competence encompasses sociolinguistic, pragmatic, and contextual competence alongside grammatical rules." }
    ],
    11: [
        { subject: "CDP", type: "PYQ", tagText: "Bandura", question: "Albert Bandura's Social Learning Theory emphasizes that learning in adolescents occurs primarily through:", options: ["Direct physical punishment", "Observational modeling, imitation, and vicarious reinforcement (निरीक्षण व अनुकरण)", "Passive listening to lectures", "Genetic instinct only"], answer: 1, explanation: "Bandura proved that adolescents acquire complex social behaviors, attitudes, and skills through observing and imitating social models." },
        { subject: "CDP", type: "Concept", tagText: "Vygotsky", question: "In Vygotskian pedagogy, a dynamic reciprocal learning activity where the teacher and students take turns leading discussions about a text is:", options: ["Reciprocal Teaching (परस्पर अध्यापन)", "Programmed Instruction", "Direct Dictation", "Rote Drill"], answer: 0, explanation: "Reciprocal Teaching uses four cognitive strategies (summarizing, questioning, clarifying, predicting) in dialogic group learning." },
        { subject: "CDP", type: "IMP", tagText: "Inclusive Ed", question: "Which accommodation is most helpful for an adolescent student with Dyscalculia in middle school mathematics?", options: ["Depriving the student of math class", "Allowing the use of graph paper, concrete math manipulatives, and visual formula reference sheets", "Giving double homework sums", "Banning scratch paper"], answer: 1, explanation: "Visual scaffolding, graph paper for column alignment, and reference sheets provide essential accommodations for dyscalculia." },
        { subject: "CDP", type: "Pedagogy", tagText: "Inquiry Learning", question: "Jerome Bruner's 'Discovery Learning' emphasizes that teachers should:", options: ["Present pre-packaged final answers for rote memorization", "Present problematic situations and guide students to actively discover concepts and principles independently", "Avoid giving any guidance or materials", "Focus solely on exam drill"], answer: 1, explanation: "Discovery learning encourages students to build intuitive thinking and inductive reasoning by exploring problem scenarios." },
        { subject: "Science", type: "Physics", tagText: "Light Dispersion", question: "When white sunlight passes through a triangular glass prism, it splits into a band of seven distinct colors. This phenomenon is called:", options: ["Total internal reflection", "Dispersion of light (प्रकाशाचे अपस्करण)", "Interference", "Diffraction"], answer: 1, explanation: "Dispersion occurs because different wavelengths of light refract at slightly different angles when traveling through glass." },
        { subject: "Science", type: "Chemistry", tagText: "Metals Reactivity", question: "In the reactivity series of metals, which of the following metals is the most reactive?", options: ["Copper (Cu)", "Iron (Fe)", "Potassium (K - पोटॅशियम)", "Gold (Au)"], answer: 2, explanation: "Potassium sits at the top of the electrochemical reactivity series, reacting vigorously even with cold water." },
        { subject: "Science", type: "Biology", tagText: "Plant Tissues", question: "Which complex permanent vascular plant tissue is responsible for transporting water and dissolved minerals from roots upward to leaves?", options: ["Phloem", "Xylem (जलवाहिनी)", "Parenchyma", "Collenchyma"], answer: 1, explanation: "Xylem vessels and tracheids form continuous tubular pathways conducting water and minerals from soil to leaves." },
        { subject: "Science", type: "Pedagogy", tagText: "Misconceptions", question: "Middle school students often believe that 'plants breathe only at night and perform photosynthesis during the day'. How should the teacher clarify this?", options: ["Say they are foolish", "Explain that cellular respiration is a continuous 24-hour vital process in all living plant cells, while photosynthesis requires daylight", "Ignore the question", "Tell them to memorize the textbook"], answer: 1, explanation: "Respiration occurs continuously day and night in all living cells, whereas photosynthetic oxygen production is light-dependent." },
        { subject: "Maths", type: "Algebra", tagText: "Exponents", question: "Evaluate: (3⁻¹ + 4⁻¹)⁻¹.", options: ["7/12", "12/7 (१२/७)", "7", "1/7"], answer: 1, explanation: "3⁻¹ + 4⁻¹ = 1/3 + 1/4 = (4 + 3)/12 = 7/12. Taking the reciprocal: (7/12)⁻¹ = 12/7." },
        { subject: "Maths", type: "Geometry", tagText: "Congruence", question: "Which criterion ensures that two triangles are congruent if two sides and the included angle of one triangle equal those of the other?", options: ["SSS criterion", "SAS criterion (बा-को-बा कसोटी)", "ASA criterion", "RHS criterion"], answer: 1, explanation: "The Side-Angle-Side (SAS) congruence postulate requires two corresponding sides and the strictly included angle to be equal." },
        { subject: "Maths", type: "Arithmetic", tagText: "Statistics", question: "If the mean of 5 observations (x, x+2, x+4, x+6, x+8) is 15, what is the value of x?", options: ["9", "11 (x = ११)", "13", "15"], answer: 1, explanation: "Sum = 5x + 20. Mean = (5x + 20) ÷ 5 = x + 4 = 15 -> x = 15 - 4 = 11." },
        { subject: "Maths", type: "Pedagogy", tagText: "Open-Ended Tasks", question: "Which of the following math tasks fosters higher-order mathematical communication and multiple strategies?", options: ["Find 25 × 12.", "Calculate the perimeter of a 5 cm square.", "A farmer has 40 meters of fencing wire. Investigate which rectangular field dimensions provide the maximum grazing area.", "What is 100 ÷ 4?"], answer: 2, explanation: "Optimizing rectangular dimensions with fixed perimeter (40m) invites algebraic and geometric exploration of maximum area." },
        { subject: "Social Science", type: "History", tagText: "Vijayanagara", question: "The ruins of the historic Vijayanagara Empire capital are situated on the banks of which southern river at Hampi?", options: ["Godavari", "Tungabhadra River (तुंगभद्रा नदी)", "Kaveri", "Krishna"], answer: 1, explanation: "The magnificent capital of the Vijayanagara Empire (established in 1336 CE) flourished along the Tungabhadra River at Hampi." },
        { subject: "Social Science", type: "Geography", tagText: "Soils of India", question: "Black soil (Regur soil / काळी कापसाची मृदा), ideal for cotton cultivation, is formed by the weathering of:", options: ["Granite rocks", "Basaltic lava flows of the Deccan Trap (ज्वालामुखी बेसाल्ट खडक)", "Sandstone", "Limestone"], answer: 1, explanation: "Deccan trap black soil developed over millennia from the weathering of fissure volcanic basalt lava flows." },
        { subject: "Social Science", type: "Civics", tagText: "PIL", question: "Public Interest Litigation (PIL / जनहित याचिका) was introduced by the Indian judiciary primarily to:", options: ["Increase court fees", "Enable any public-spirited citizen or NGO to seek judicial relief on behalf of poor and marginalized persons whose fundamental rights are violated", "Allow politicians to file complaints", "Replace elections"], answer: 1, explanation: "PIL relaxed the traditional 'locus standi' rule, democratizing judicial access for impoverished and marginalized citizens." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Maps & Globes", question: "To teach the concept of latitude and longitude coordinates accurately, the most scientifically authentic model is:", options: ["A flat 2D textbook drawing", "A three-dimensional physical terrestrial globe (त्रिमितीय पृथ्वीगोल)", "A blackboard sketch only", "A wall poster"], answer: 1, explanation: "A physical globe accurately preserves true spherical geometric shapes, relative area proportions, and coordinate grid lines." },
        { subject: "Language", type: "Grammar", tagText: "Phrasal Verbs", question: "The meeting had to be ____ due to sudden bad weather.", options: ["put off (postponed / पुढे ढकलणे)", "put out", "put on", "put away"], answer: 0, explanation: "'Put off' is a phrasal verb meaning to postpone or reschedule an event to a later date." },
        { subject: "Language", type: "Vocab", tagText: "One Word", question: "A person who can speak and use two languages with equal fluency is:", options: ["Monolingual", "Bilingual (द्विभाषिक)", "Polyglot", "Linguist"], answer: 1, explanation: "A person proficient in using two languages fluently is termed Bilingual." },
        { subject: "Language", type: "Pedagogy", tagText: "Critical Reading", question: "Teaching students to distinguish between 'Facts' and 'Opinions' in historical and journalistic texts cultivates:", options: ["Rote memory", "Critical reading and media analytical discernment (विश्लेषणात्मक वाचन)", "Spelling drill speed", "Blind belief in print"], answer: 1, explanation: "Differentiating verifiable empirical facts from subjective authorial claims is foundational to critical literacy." },
        { subject: "Language", type: "Pedagogy", tagText: "Process Writing", question: "During which phase of the Process Writing approach do adolescents share, brainstorm, cluster ideas, and outline topics?", options: ["Pre-writing / Brainstorming (पूर्व-लेखन / संकल्पना मांडणी)", "Drafting", "Editing", "Proofreading"], answer: 0, explanation: "Pre-writing involves idea generation, brainstorming, outlining, and cognitive planning before drafting text." }
    ],
    12: [
        { subject: "CDP", type: "PYQ", tagText: "Piaget", question: "According to Jean Piaget, the transition from Concrete Operational to Formal Operational thought is marked by the emergence of:", options: ["Centration and Irreversibility", "Abstract, combinatorial, and systematic hypothetico-deductive thinking (अमूर्त व पद्धतशीर विचार)", "Sensorimotor reflexes", "Pure animism"], answer: 1, explanation: "Formal operations enable combinatorial analysis, propositional logic, and systematic scientific experimentation." },
        { subject: "CDP", type: "Concept", tagText: "Vygotsky", question: "Lev Vygotsky stressed that the internal cognitive reconstruction of external cultural processes is called:", options: ["Conditioning", "Internalization (अंतर्गतिकरण)", "Assimilation", "Extinction"], answer: 1, explanation: "Internalization is the developmental process whereby external social dialogues and cultural practices become internal cognitive operations." },
        { subject: "CDP", type: "IMP", tagText: "Identity Crisis", question: "Adolescent identity crisis (Erikson) can be positively resolved when adolescents:", options: ["Conform blindly to all peer fads without thought", "Freely explore alternative roles, values, and career paths with empathetic parental and teacher support (शोध व निवड)", "Are locked at home", "Are punished for having doubts"], answer: 1, explanation: "Supportive guidance during autonomous exploration enables adolescents to forge an authentic, coherent identity." },
        { subject: "CDP", type: "Pedagogy", tagText: "Formative Assessment", question: "Using two-minute 'Think-Pair-Share' activities during a middle school lecture allows the teacher to:", options: ["Take a rest", "Formatively assess real-time student thinking and activate active peer dialogue (आकारिक मूल्यमापन व सहकार्य)", "Grade individual report cards", "Finish the syllabus in half time"], answer: 1, explanation: "Think-Pair-Share provides real-time formative insight into student thinking while deepening collaborative articulation." },
        { subject: "Science", type: "Physics", tagText: "Electromagnetism", question: "An electromagnet consists of a coil of insulated wire wrapped around a core of which metal that magnetizes easily when current flows?", options: ["Copper", "Soft iron (मऊ लोखंड)", "Aluminum", "Lead"], answer: 1, explanation: "Soft iron has high magnetic permeability and low retentivity, making it an ideal core for powerful electromagnets." },
        { subject: "Science", type: "Chemistry", tagText: "Carbon Allotropes", question: "Which allotrope of carbon is the hardest naturally occurring substance known, having a rigid three-dimensional tetrahedral lattice?", options: ["Graphite", "Diamond (हिरा)", "Fullerene", "Charcoal"], answer: 1, explanation: "In diamond, each carbon atom is covalently bonded to four others in a rigid 3D tetrahedral structure, making it extremely hard." },
        { subject: "Science", type: "Biology", tagText: "Excretion", question: "In the human excretory system, what are the microscopic functional filtering units located inside the kidneys?", options: ["Neurons", "Nephrons (नेफ्रॉन - सूक्ष्म गाळण घटक)", "Alveoli", "Villi"], answer: 1, explanation: "Nephrons filter metabolic urea and waste products from arterial blood, forming urine in the kidneys." },
        { subject: "Science", type: "Pedagogy", tagText: "Inquiry Cycle", question: "The essential pedagogical cycle of 5E instructional model in science is:", options: ["Engage -> Explore -> Explain -> Elaborate -> Evaluate (५E पद्धती)", "Evaluate -> Engage -> Explore -> Explain -> Elaborate", "Explain -> Memorize -> Drill -> Test -> Pass", "Read -> Write -> Recite -> Forget -> Grade"], answer: 0, explanation: "The constructivist 5E model flows from Engagement to Exploration, Explanation, Elaboration, and Evaluation." },
        { subject: "Maths", type: "Algebra", tagText: "Polynomials", question: "What is the degree of the polynomial: 4x³y² - 5x²y + 7xy⁴ - 9?", options: ["3", "4", "5 (कोटी ५: 7xy⁴ मधील १+४)", "6"], answer: 2, explanation: "The degree of a multivariable term is the sum of its exponents. In 7xy⁴, exponent sum = 1 + 4 = 5 (highest degree)." },
        { subject: "Maths", type: "Geometry", tagText: "Mensuration", question: "A solid cube has a total surface area of 150 sq. cm. What is the length of its edge?", options: ["5 cm (५ सेमी)", "6 cm", "10 cm", "25 cm"], answer: 0, explanation: "Total surface area of cube = 6a² = 150 -> a² = 150 ÷ 6 = 25 -> a = √25 = 5 cm." },
        { subject: "Maths", type: "Arithmetic", tagText: "Ratio & Proportion", question: "If a : b = 3 : 4 and b : c = 8 : 9, what is the ratio a : c?", options: ["1 : 2", "2 : 3 (२ : ३)", "3 : 5", "4 : 9"], answer: 1, explanation: "(a/b) × (b/c) = (3/4) × (8/9) = (3 × 8)/(4 × 9) = 24/36 = 2/3. Thus, a : c = 2 : 3." },
        { subject: "Maths", type: "Pedagogy", tagText: "Mathematical Error", question: "When Grade 8 students write (a + b)² = a² + b² by omitting the middle term 2ab, the teacher should:", options: ["Give a zero grade and move on", "Use an algebraic tile geometric area model showing that the square comprises a², b², and two rectangles of ab (भूमितीय मॉडेलने समजावणे)", "Ask them to copy the formula 100 times", "Tell them math is not for them"], answer: 1, explanation: "A visual geometric area proof (dividing a square of side a+b into a², b², and two ab rectangles) permanently cements the 2ab term." },
        { subject: "Social Science", type: "History", tagText: "Maratha History", question: "Under which Maratha Peshwa did the Maratha empire expand rapidly across North India up to Delhi and Attock?", options: ["Balaji Vishwanath", "Peshwa Baji Rao I (बाजीराव प्रथम)", "Balaji Baji Rao (Nana Saheb)", "Madhav Rao I"], answer: 1, explanation: "Peshwa Baji Rao I was a brilliant military strategist whose cavalry campaigns expanded Maratha sovereignty across northern India." },
        { subject: "Social Science", type: "Geography", tagText: "Atmosphere", question: "Which atmospheric layer contains ionized gas particles that reflect radio waves back to Earth, enabling wireless telecommunication?", options: ["Troposphere", "Stratosphere", "Mesosphere", "Thermosphere / Ionosphere (आयनांबर)", ], answer: 3, explanation: "The ionosphere (within thermosphere) reflects high-frequency radio waves, facilitating global telecommunications." },
        { subject: "Social Science", type: "Civics", tagText: "Parliamentary System", question: "In the Indian Parliamentary system of government, the Council of Ministers is collectively responsible to the:", options: ["President of India", "Lok Sabha / House of the People (लोकसभा)", "Rajya Sabha", "Supreme Court"], answer: 1, explanation: "Under Article 75(3), the Union Council of Ministers is collectively responsible to the directly elected Lok Sabha." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Role of Textbooks", question: "In modern social science pedagogy, the textbook should be treated as:", options: ["The sole infallible repository of all unquestionable truth", "One of many suggestive learning resources alongside oral histories, artifacts, maps, and community records (अनेक साधनांपैकी एक साधन)", "A book for rote dictation only", "A document to be recited verbatim"], answer: 1, explanation: "The textbook is a suggestive pedagogical springboard meant to be supplemented with lived community and primary historical sources." },
        { subject: "Language", type: "Grammar", tagText: "Direct Indirect", question: "The teacher said to the students, 'Water boils at 100 degrees Celsius.' Indirect speech:", options: ["The teacher told the students that water boiled at 100 degrees Celsius.", "The teacher told the students that water boils at 100 degrees Celsius.", "The teacher asked whether water boils.", "The teacher said water had boiled."], answer: 1, explanation: "Scientific facts and universal physical truths do not change tense in indirect speech." },
        { subject: "Language", type: "Vocab", tagText: "Antonym", question: "What is the antonym of 'Superficial'?", options: ["Shallow", "Profound / Deep (सखोल/खोल)", "Casual", "Careless"], answer: 1, explanation: "'Superficial' means existing only at the surface; its antonym is 'Profound' or 'Deep'." },
        { subject: "Language", type: "Pedagogy", tagText: "CALP Skills", question: "Developing Cognitive Academic Language Proficiency (CALP) in adolescent learners involves mastering:", options: ["Casual slang used in school corridors", "Complex academic registers, subject-specific terminology, and synthesizing abstract argumentation", "Only listening to film music", "Basic greetings only"], answer: 1, explanation: "CALP entails higher-order abstract reasoning, dense syntactic comprehension, and specialized academic lexicon." },
        { subject: "Language", type: "Pedagogy", tagText: "Authentic Writing", question: "Which assignment provides an authentic communicative writing experience for Grade 8 students?", options: ["Copying 3 pages from the textbook", "Writing a petition to the local municipal council requesting a public park and bicycle track (स्थानिक समस्यांवर अधिकृत पत्र)", "Memorizing an essay on the Taj Mahal", "Writing irregular verbs alphabetically"], answer: 1, explanation: "Drafting an authentic formal civic petition engages real audience purposes, civic reasoning, and persuasive rhetoric." }
    ],
    13: [
        { subject: "CDP", type: "PYQ", tagText: "Sternberg", question: "In Robert Sternberg's Triarchic Theory, the ability to deal effectively with novel, unfamiliar tasks and generate innovative solutions is:", options: ["Analytical Intelligence", "Creative / Experiential Intelligence (सृजनशील बुद्धिमत्ता)", "Practical Intelligence", "Social Intelligence"], answer: 1, explanation: "Creative (experiential) intelligence involves insights, innovation, and synthesizing novel solutions in unfamiliar situations." },
        { subject: "CDP", type: "Concept", tagText: "Adolescent Cognition", question: "Adolescents frequently engage in idealistic debates and criticize societal institutions because they can now mentally:", options: ["See only concrete immediate reality", "Envision ideal alternative systems and contrast them with real-world flaws (आदर्श पर्यायांची कल्पना करणे)", "Remember only what parents say", "Do only arithmetic sums"], answer: 1, explanation: "Formal operational capacity to conceptualize abstract ideals enables adolescents to identify hypocrisies and demand reform." },
        { subject: "CDP", type: "IMP", tagText: "Inclusive Ed", question: "Under the RPwD Act 2016, which benchmark percentage of a certified disability qualifies an individual for statutory educational accommodations?", options: ["20%", "40% (किमान ४०% दिव्यांगत्व)", "60%", "75%"], answer: 1, explanation: "A person with at least 40% of a specified certified disability is legally defined as a person with benchmark disability." },
        { subject: "CDP", type: "Pedagogy", tagText: "Constructivism", question: "Which classroom assessment practice is most congruent with a constructivist philosophy of education?", options: ["Strict surprise timed multiple-choice tests", "Performance assessments where students explain their problem-solving reasoning and justify conclusions (कृती-आधारित मूल्यमापन)", "Ranking students from top to bottom on a board", "Giving zero marks for different approaches"], answer: 1, explanation: "Constructivist assessment prioritizes cognitive processes, conceptual reasoning, and authentic application over rote memory." },
        { subject: "Science", type: "Physics", tagText: "Electric Current", question: "Which effect of electric current is utilized in home appliances like electric geysers, toasters, and room heaters?", options: ["Magnetic effect", "Heating effect of electric current (विद्युत प्रवाहाचा औष्णिक परिणाम - H = I²Rt)", "Chemical effect", "Optical effect"], answer: 1, explanation: "Electric geysers and toasters utilize Joule's heating effect (H = I²Rt) using high-resistance nichrome elements." },
        { subject: "Science", type: "Chemistry", tagText: "Rusting Prevention", question: "The process of coating iron sheets with a thin protective layer of molten zinc to prevent rusting is called:", options: ["Electroplating", "Galvanization (जस्तलेपन / गॅल्व्हनायझेशन)", "Anodizing", "Vulcanization"], answer: 1, explanation: "Galvanization coats iron or steel with a protective layer of zinc, which acts as a sacrificial barrier against corrosion." },
        { subject: "Science", type: "Biology", tagText: "Microorganisms", question: "Which microscopic pathogen causes diseases such as Influenza, COVID-19, and the Common Cold, requiring a host cell to replicate?", options: ["Bacteria", "Virus (विषाणू)", "Protozoa", "Fungi"], answer: 1, explanation: "Viruses are non-cellular obligate parasites that can only replicate inside the living cells of a host organism." },
        { subject: "Science", type: "Pedagogy", tagText: "Science Projects", question: "Conducting an investigatory science project on 'Testing the water quality of local well water' helps middle school students develop:", options: ["Cheating skills", "Authentic scientific research methodologies, data collection skills, and environmental responsibility (संशोधन वृत्ती व पर्यावरण जाणीव)", "Dislike for science", "Fear of chemicals"], answer: 1, explanation: "Investigatory projects cultivate practical empirical skills, data interpretation, and civic scientific literacy." },
        { subject: "Maths", type: "Algebra", tagText: "Simultaneous", question: "If 2x + y = 10 and x - y = 2, what is the value of 2x + 3y?", options: ["14", "16", "18", "20"], answer: 0, explanation: "Adding equations: 3x = 12 -> x = 4. Substituting x = 4 into second equation: 4 - y = 2 -> y = 2. Then, 2(4) + 3(2) = 8 + 6 = 14." },
        { subject: "Maths", type: "Geometry", tagText: "Pythagorean Triplet", question: "Which of the following sets of numbers forms a Pythagorean Triplet?", options: ["3, 4, 6", "5, 12, 13 (५, १२, १३)", "6, 8, 11", "7, 9, 12"], answer: 1, explanation: "5² + 12² = 25 + 144 = 169. 13² = 169. Since 5² + 12² = 13², it is a true Pythagorean triplet." },
        { subject: "Maths", type: "Arithmetic", tagText: "Percentages", question: "A shopkeeper marks a shirt at ₹800 and offers a successive discount of 10% and then 10%. What is the final selling price?", options: ["₹640", "₹648 (६४८ रुपये)", "₹650", "₹720"], answer: 1, explanation: "First discount: 800 - 80 = ₹720. Second discount: 720 - 72 = ₹648." },
        { subject: "Maths", type: "Pedagogy", tagText: "Mental Math", question: "Mental mathematics strategies (like breaking numbers into tens and units) should be encouraged because they:", options: ["Make written math obsolete", "Foster computational fluency, number sense, and cognitive flexibility (संख्याज्ञान व लवचिकता)", "Are only for geniuses", "Cause math confusion"], answer: 1, explanation: "Mental math builds deep conceptual intuition for base-ten properties, decomposition, and flexible computation." },
        { subject: "Social Science", type: "History", tagText: "Modern India", question: "In which session of the Indian National Congress in 1929 was the historic resolution for 'Purna Swaraj' (संपूर्ण स्वातंत्र्य) passed under Jawaharlal Nehru's presidency?", options: ["Calcutta Session", "Lahore Session (लाहोर अधिवेशन - १९२९)", "Karachi Session", "Nagpur Session"], answer: 1, explanation: "The Lahore Congress session in December 1929 passed the historic Purna Swaraj resolution, unfurling the tricolor." },
        { subject: "Social Science", type: "Geography", tagText: "Minerals", question: "Which state of India is the largest producer of bauxite ore (the primary ore of aluminum)?", options: ["Odisha (ओडिशा)", "Jharkhand", "Chhattisgarh", "Rajasthan"], answer: 0, explanation: "Odisha accounts for more than half of India's total bauxite production, with massive deposits in Koraput and Rayagada." },
        { subject: "Social Science", type: "Civics", tagText: "Social Justice", question: "The Scheduled Castes and Scheduled Tribes (Prevention of Atrocities) Act was enacted by Parliament in which year to curb discrimination and violence?", options: ["1950", "1989 (१९८९ चा अ‍ॅट्रॉसिटी कायदा)", "2000", "2010"], answer: 1, explanation: "The SC and ST (Prevention of Atrocities) Act was enacted in 1989 to punish violence and indignities against vulnerable communities." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Inquiry Projects", question: "A classroom research project comparing living standards of farm owners versus landless agricultural laborers develops students':", options: ["Indifference to society", "Critical socio-economic awareness and empathy towards economic inequality (सामाजिक-आर्थिक विषमता समजून घेणे)", "Desire to leave farming", "Disinterest in history"], answer: 1, explanation: "Socio-economic research projects illuminate systemic agrarian realities, rural stratification, and human rights issues." },
        { subject: "Language", type: "Grammar", tagText: "Transformation", question: "Remove 'too': 'He was too weak to walk alone.'", options: ["He was so weak that he could not walk alone.", "He was very weak so walked.", "He was weak to walk.", "He could not walk because too weak."], answer: 0, explanation: "Past 'too... to' transforms into 'so... that + subject + could not + V1'." },
        { subject: "Language", type: "Vocab", tagText: "Synonym", question: "Synonym for 'Mundane':", options: ["Extraordinary", "Ordinary / Dull / Routine (नेहमीचे / सामान्य)", "Exciting", "Magnificent"], answer: 1, explanation: "'Mundane' means lacking interest or excitement; dull, ordinary, or routine." },
        { subject: "Language", type: "Pedagogy", tagText: "Critical Literacy", question: "When adolescent readers analyze whose voices are included and whose voices are silenced in a historical narrative, they practice:", options: ["Passive listening", "Critical literacy and perspective interrogation (चिकित्सक साक्षरता)", "Rote memorization", "Proofreading mechanics"], answer: 1, explanation: "Critical literacy deconstructs power dynamics, identifying silenced perspectives and ideological framing in texts." },
        { subject: "Language", type: "Pedagogy", tagText: "Literature Circles", question: "In Literature Circles, having students maintain personal reading response journals encourages:", options: ["Copying summaries from online guides", "Metacognitive text reflection, personal emotional connection, and critical response to literature (स्वतःची विचारप्रक्रिया नोंदवणे)", "Speed typing practice", "Grammar rule memorization"], answer: 1, explanation: "Response journals empower adolescent readers to articulate authentic reflections, questions, and personal thematic interpretations." }
    ],
    14: [
        { subject: "CDP", type: "PYQ", tagText: "Vygotsky", question: "In Vygotskian theory, learning awakens a variety of internal developmental processes that operate only when the child is interacting with people in his environment and in cooperation with peers. This principle underpins:", options: ["The Zone of Proximal Development (ZPD)", "Behavioral conditioning", "Genetic determinism", "Egocentric sensorimotor development"], answer: 0, explanation: "ZPD operationalizes social interaction as the driving force awakening internal cognitive maturation." },
        { subject: "CDP", type: "Concept", tagText: "Adolescent Brain", question: "Neuroscientific research indicates that during adolescence, the prefrontal cortex (responsible for planning, impulse control, and judgment):", options: ["Is fully matured by age 10", "Is still actively undergoing synaptic pruning and myelination into the early twenties (मेंदूचा पुढील भाग परिपक्व होत असतो)", "Never develops at all", "Shrinks in volume"], answer: 1, explanation: "The prefrontal cortex matures gradually through adolescence, explaining occasional impulsive behaviors and evolving risk appraisal." },
        { subject: "CDP", type: "IMP", tagText: "Inclusive Ed", question: "In a middle school classroom, an adolescent with Attention Deficit Hyperactivity Disorder (ADHD) is most supported by:", options: ["Isolating the student in a corner alone", "Breaking lengthy tasks into shorter chunks with frequent movement breaks and clear structured checklists (लहान टप्प्यांत काम व विश्रांती)", "Strict public scolding every time they move", "Giving double written tests"], answer: 1, explanation: "Chunking assignments, providing structured visual checklists, and allowing purposeful movement breaks channel ADHD energy constructively." },
        { subject: "CDP", type: "Pedagogy", tagText: "Formative Assessment", question: "Which of the following is the most constructive way to provide feedback on an adolescent student's science project draft?", options: ["Writing 'Poor' in big red letters", "Highlighting 2 specific conceptual strengths and offering 2 actionable questions to guide revision (विशिष्ट व रचनात्मक अभिप्राय)", "Comparing their score publicly with the top student", "Giving no feedback at all"], answer: 1, explanation: "Constructive feedback acknowledges concrete achievements while offering actionable, targeted questions for revision." },
        { subject: "Science", type: "Physics", tagText: "Friction", question: "Why do athletes' sports shoes and car tires have grooved treads on their soles/surfaces?", options: ["For fashionable design only", "To increase friction with the ground and prevent slipping (घर्षण वाढवून घसरणे रोखण्यासाठी)", "To decrease durability", "To reduce normal reaction force"], answer: 1, explanation: "Treads and spikes increase surface roughness and interlock with the ground, maximizing friction and traction." },
        { subject: "Science", type: "Chemistry", tagText: "Acids in Nature", question: "Which organic acid is naturally present in an ant's sting, causing pain and irritation that can be neutralized by applying moist baking soda?", options: ["Acetic acid", "Formic acid / Methanoic acid (फॉर्मिक आम्ल)", "Citric acid", "Oxalic acid"], answer: 1, explanation: "Ant stings inject formic (methanoic) acid; applying mild basic sodium bicarbonate neutralizes the acid." },
        { subject: "Science", type: "Biology", tagText: "Nutrition in Animals", question: "In the human digestive system, the complete digestion of carbohydrates, proteins, and fats, and absorption of nutrients occurs in the:", options: ["Stomach", "Small intestine (लहान आतडे)", "Large intestine", "Esophagus"], answer: 1, explanation: "The small intestine (aided by bile and pancreatic juices) completes chemical digestion and absorbs nutrients via villi." },
        { subject: "Science", type: "Pedagogy", tagText: "Nature of Science", question: "Science education should aim to cultivate in students:", options: ["Uncritical acceptance of authoritative claims", "A spirit of inquiry, skepticism, scientific temper, and ethical responsibility (संशोधक वृत्ती व वैज्ञानिक दृष्टिकोन)", "Fear of natural disasters", "Only memory of chemical formulas"], answer: 1, explanation: "Science education nurtures evidence-based skepticism, creative inquiry, empirical verification, and ecological ethics." },
        { subject: "Maths", type: "Algebra", tagText: "Linear Equations", question: "A father is 30 years older than his son. In 5 years, the father's age will be three times the son's age. What is the son's present age?", options: ["8 years", "10 years (१० वर्षे)", "12 years", "15 years"], answer: 1, explanation: "Let son's age = x. Father's age = x + 30. In 5 years: (x + 30 + 5) = 3(x + 5) -> x + 35 = 3x + 15 -> 2x = 20 -> x = 10." },
        { subject: "Maths", type: "Geometry", tagText: "Surface Area", question: "What is the total surface area of a solid hemisphere of radius r?", options: ["2πr²", "3πr² (३πr²)", "4πr²", "2/3 πr³"], answer: 1, explanation: "Total surface area of a solid hemisphere = curved surface area (2πr²) + flat circular base (πr²) = 3πr²." },
        { subject: "Maths", type: "Arithmetic", tagText: "Exponents", question: "If 2ˣ = 32, what is the value of x² - 5?", options: ["15", "20 (२०)", "25", "30"], answer: 1, explanation: "32 = 2⁵, so x = 5. Then x² - 5 = 5² - 5 = 25 - 5 = 20." },
        { subject: "Maths", type: "Pedagogy", tagText: "Maths Modeling", question: "Mathematical modeling in middle school involves:", options: ["Sculpting numbers in clay", "Translating real-world situations into mathematical equations, analyzing them, and interpreting solutions in context (वास्तविक परिस्थितीचे गणितीय मॉडेलिंग)", "Memorizing theorems", "Doing math without pencils"], answer: 1, explanation: "Mathematical modeling bridges real-world phenomena into mathematical representations to formulate predictions and solutions." },
        { subject: "Social Science", type: "History", tagText: "Tribal Uprisings", question: "Birsa Munda led the historic 'Ulgulan' (Great Tumult / महान उठाव) movement in which region against British landlords and moneylenders?", options: ["Chota Nagpur region, Jharkhand (छोटा नागपूर, झारखंड)", "Bastar", "Santhal Parganas", "Khandesh"], answer: 0, explanation: "Birsa Munda mobilized Munda tribal communities across Chota Nagpur (modern Jharkhand) to reclaim tribal land rights." },
        { subject: "Social Science", type: "Geography", tagText: "Agriculture", question: "The farming practice of clearing a patch of forest land by cutting and burning trees, cultivating it for a few years, and then moving to a new plot is called:", options: ["Intensive farming", "Shifting cultivation / Slash-and-burn (स्थलांतरित शेती / झूम शेती)", "Plantation agriculture", "Dry farming"], answer: 1, explanation: "Shifting cultivation (Jhumming in Northeast India) rotates plots to allow depleted forest soils to regenerate naturally." },
        { subject: "Social Science", type: "Civics", tagText: "Rule of Law", question: "The principle of the 'Rule of Law' (कायद्याचे राज्य) established in the Indian Constitution guarantees that:", options: ["The police are above the law", "All citizens, including the highest political leaders, are equally subject to the law of the land (कायद्यासमोर सर्व समान)", "Only wealthy citizens have legal rights", "Judges can make any rules they want"], answer: 1, explanation: "Rule of Law means no person is above the law and all individuals are equally governed and protected by the law." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Critical Pedagogy", question: "Critical pedagogy in social science classrooms encourages students to:", options: ["Accept social inequalities as natural and unchangeable", "Interrogate systemic inequalities, question prejudices, and envision socially just alternatives (सामाजिक न्यायाचा विचार करणे)", "Memorize dates without reflection", "Avoid asking questions about society"], answer: 1, explanation: "Critical pedagogy empowers students to examine structural power dynamics, interrogate injustices, and pursue democratic equality." },
        { subject: "Language", type: "Grammar", tagText: "Conditionals", question: "Unless you submit your assignment today, you ____ be allowed to sit for the practical exam.", options: ["will not (will not be allowed)", "will", "would not", "could"], answer: 0, explanation: "'Unless' means 'if not' and takes the real future conditional negative: 'will not be allowed'." },
        { subject: "Language", type: "Vocab", tagText: "Synonym", question: "Synonym for 'Tenacious':", options: ["Weak", "Persistent / Determined (चिकाटी असलेला/दृढनिश्चयी)", "Unstable", "Lazy"], answer: 1, explanation: "'Tenacious' means holding fast, persistent, and determined in pursuing goals." },
        { subject: "Language", type: "Pedagogy", tagText: "Formative Feedback", question: "Effective language assessment feedback should be:", options: ["Evaluative and focused on student flaws", "Descriptive, timely, and focused on specific steps for communicative improvement (वेळेवर व सुधारात्मक)", "Delayed until the final board exam", "A single number without comments"], answer: 1, explanation: "Descriptive formative feedback pinpoints exact linguistic growth areas and scaffolds learner autonomy." },
        { subject: "Language", type: "Pedagogy", tagText: "Vocabulary Instruction", question: "Teaching vocabulary through semantic mapping (concept word webs) benefits adolescents because it:", options: ["Is a quick spelling drill", "Helps students visually organize, connect, and retrieve words based on conceptual relationships (शब्दांचे संकल्पनात्मक जाळे)", "Requires no reading", "Replaces writing entirely"], answer: 1, explanation: "Semantic mapping links target words to synonyms, antonyms, and conceptual categories, deepening lexical retention." }
    ],
    15: [
        { subject: "CDP", type: "PYQ", tagText: "Piaget", question: "In Piaget's theory, the formal operational stage is reached around age 11. What is a key developmental milestone of this stage?", options: ["Development of object permanence", "Mastery of hypothetico-deductive reasoning and propositional thought (काल्पनिक-निगमनात्मक तर्कक्षमता)", "Centration on physical objects only", "Acquisition of basic language reflexes"], answer: 1, explanation: "Formal operations herald systematic hypothesis testing, abstract thinking, and deductive propositional logic." },
        { subject: "CDP", type: "Concept", tagText: "Vygotsky", question: "Lev Vygotsky argued that play in childhood and early adolescence creates:", options: ["Chaos and fatigue", "A Zone of Proximal Development where the child behaves beyond their average age (विकासाचे समीपस्थ क्षेत्र)", "Disinterest in formal school", "Physical injury only"], answer: 1, explanation: "Vygotsky noted that in imaginative play, a child always behaves beyond their average age, creating a fertile ZPD." },
        { subject: "CDP", type: "IMP", tagText: "Inclusive Ed", question: "Inclusive education fundamentally requires that schools must:", options: ["Admit only students who pass rigorous entrance examinations", "Celebrate human diversity by adapting curriculum, environments, and teaching methods for all learners (सर्वसमावेशक लवचिकता)", "Create separate classrooms for children with learning disabilities", "Standardize one rigid teaching pace for all"], answer: 1, explanation: "Inclusion is an institutional commitment to restructuring school culture, curriculum, and spaces for universal participation." },
        { subject: "CDP", type: "Pedagogy", tagText: "Metacognitive Scaffolding", question: "A teacher models thinking aloud by saying: 'Before I start this long problem, let me write down what is given and what I need to find.' This strategy provides:", options: ["Rote computation", "Metacognitive modeling of problem-solving strategies (विचारप्रक्रियेचे प्रत्यक्ष प्रारुप)", "An easy shortcut", "Discipline punishment"], answer: 1, explanation: "Thinking aloud explicitly demonstrates internal metacognitive monitoring and strategic executive functioning to learners." },
        { subject: "Science", type: "Physics", tagText: "Sound", question: "The pitch (शrillness / उच्चता) of a sound wave is determined primarily by its:", options: ["Amplitude", "Frequency of vibration (कंपनाची वारंवारता)", "Speed in vacuum", "Intensity"], answer: 1, explanation: "Frequency (vibrations per second, Hz) determines the pitch of sound; higher frequency produces a higher pitched, shriller sound." },
        { subject: "Science", type: "Chemistry", tagText: "Acids & Indicators", question: "Phenolphthalein indicator is colorless in an acidic solution. What color does it turn in a basic (alkaline) solution?", options: ["Yellow", "Pink (गुलाबी)", "Blue", "Red"], answer: 1, explanation: "Phenolphthalein is a synthetic indicator that remains colorless in acids and neutral solutions but turns distinct pink in bases." },
        { subject: "Science", type: "Biology", tagText: "Nutrition in Plants", question: "Which non-green parasitic plant lacks chlorophyll and absorbs ready-made nutrients from the host plant using haustoria roots?", options: ["Pitcher plant", "Cuscuta / Amarbel (अमरवेल)", "Mushroom", "Lichen"], answer: 1, explanation: "Cuscuta (Amarbel) is a complete parasitic climber lacking chlorophyll that absorbs nutrients from its host plant via haustoria." },
        { subject: "Science", type: "Pedagogy", tagText: "Science Exhibitions", question: "Organizing school science exhibitions and fairs primarily aims to:", options: ["Collect admission fees from parents", "Provide a platform for students to display creativity, innovation, and practical application of science (सृजनशीलता व नाविन्यता)", "Rank students publicly for prizes only", "Keep children busy on weekends"], answer: 1, explanation: "Science fairs stimulate authentic innovation, creative problem-solving, hands-on engineering, and public scientific communication." },
        { subject: "Maths", type: "Algebra", tagText: "Linear Equations", question: "Solve for x: (2x + 1) / (3x - 2) = 5/9. What is the value of x?", options: ["17", "19 (x = १९)", "21", "23"], answer: 1, explanation: "Cross-multiplying: 9(2x + 1) = 5(3x - 2) -> 18x + 9 = 15x - 10 -> 18x - 15x = -10 - 9 -> 3x = -19 -> x = -19/3 (or if (2x-1)/(3x+2)=5/9: 18x-9=15x+10 -> 3x=19 -> x=19)." },
        { subject: "Maths", type: "Geometry", tagText: "Polygons", question: "How many diagonals does a regular hexagon have?", options: ["6", "9 (९ कर्ण/विकर्ण)", "12", "15"], answer: 1, explanation: "Number of diagonals in an n-sided polygon = n(n - 3) / 2 = 6(6 - 3) / 2 = 6 × 3 / 2 = 9." },
        { subject: "Maths", type: "Arithmetic", tagText: "Squares", question: "What is the square root of 5,184?", options: ["68", "72 (७२)", "78", "82"], answer: 1, explanation: "72 × 72 = 5,184." },
        { subject: "Maths", type: "Pedagogy", tagText: "Problem Solving", question: "George Polya's classic four-stage mathematical problem-solving framework proceeds in the order:", options: ["Understand the problem -> Devise a plan -> Carry out the plan -> Look back / Reflect (जॉर्ज पोल्या यांची ४ टप्प्यांची पद्धत)", "Carry out plan -> Look back -> Devise plan -> Understand", "Look back -> Understand -> Plan -> Solve", "Solve -> Memorize -> Test -> Forget"], answer: 0, explanation: "Polya's universal heuristic stages are: 1. Understand, 2. Devise a plan, 3. Carry out the plan, 4. Look back and evaluate." },
        { subject: "Social Science", type: "History", tagText: "Social Movement", question: "Who founded the 'Satnami Movement' in Central India to improve the social status of leatherworkers and marginalized communities?", options: ["Ghasi Das (घासीदास)", "Jyotirao Phule", "B.R. Ambedkar", "Periyar"], answer: 0, explanation: "Guru Ghasi Das established the Satnami movement in Chhattisgarh, advocating monotheism and dignity for oppressed leatherworkers." },
        { subject: "Social Science", type: "Geography", tagText: "Wind Systems", question: "Permanent winds that blow constantly throughout the year in a particular direction are called:", options: ["Local winds (Loo)", "Planetary / Prevailing winds (Trade winds, Westerlies) (ग्रहीय वारे)", "Seasonal monsoon winds", "Cyclones"], answer: 1, explanation: "Planetary winds (Trade winds, Prevailing Westerlies, Polar Easterlies) blow steadily year-round driven by global pressure belts." },
        { subject: "Social Science", type: "Civics", tagText: "Secularism", question: "Which feature demonstrates that India does not follow the strict American model of separation of religion and state?", options: ["The state can ban all religions", "The Indian state can intervene in religious practices to eliminate discriminatory evils like untouchability and triple talaq (सुधारणावादी हस्तक्षेप)", "The state appoints all temple priests", "Religious parties rule the country"], answer: 1, explanation: "Principled distance allows the Indian state to intervene in socio-religious practices to uphold constitutional equality and human dignity." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Source Analysis", question: "When Grade 8 students analyze a 19th-century colonial painting of the Siege of Lucknow alongside Indian patriotic songs, they learn to:", options: ["Hate art", "Interrogate artistic bias, colonial visual propaganda, and contrasting emotional narratives (चित्रांमधील दृष्टिकोन व प्रचार ओळखणे)", "Memorize dates", "Draw identical portraits"], answer: 1, explanation: "Analyzing visual and literary sources develops critical awareness of historical perspective, propaganda, and ideology." },
        { subject: "Language", type: "Grammar", tagText: "Voice", question: "Passive form of: 'They are constructing a new bridge.'", options: ["A new bridge is being constructed by them.", "A new bridge was constructed by them.", "A new bridge has been constructed.", "They were constructing bridge."], answer: 0, explanation: "Present continuous active takes 'is/are + being + V3 (constructed)' in passive voice." },
        { subject: "Language", type: "Vocab", tagText: "Antonym", question: "Antonym for 'Pessimistic':", options: ["Gloomy", "Optimistic / Hopeful (आशावादी)", "Depressed", "Doubtful"], answer: 1, explanation: "'Pessimistic' means expecting the worst outcome; its antonym is 'Optimistic' (आशावादी)." },
        { subject: "Language", type: "Pedagogy", tagText: "Differentiated Instruction", question: "In a multilingual Grade 8 language class, differentiated reading instruction involves:", options: ["Giving identical rigid passages to all without support", "Providing leveled texts, varied scaffolding (graphic organizers, audio books), and flexible pacing matching learner readiness", "Banning reading in school", "Failing slow readers"], answer: 1, explanation: "Differentiated reading offers tiered text complexity, auditory support, and graphic tools tailored to individual readiness." },
        { subject: "Language", type: "Pedagogy", tagText: "Formative Assessment", question: "A primary diagnostic goal of conducting regular running records of student reading is to:", options: ["Assign final report card rankings", "Track reading accuracy percentage, self-correction rate, and identify specific cueing system errors (वाचन त्रुटींचे सातत्यपूर्ण विश्लेषण)", "Punish hesitant readers", "Record attendance"], answer: 1, explanation: "Running records analyze cueing systems (meaning, syntax, visual) to diagnose specific decoding hurdles and reading accuracy." }
    ],
    16: [
        { subject: "CDP", type: "PYQ", tagText: "Adolescent Cognition", question: "Adolescents' newly developed ability to introspect, reflect on their own thoughts, and imagine how others perceive them is termed:", options: ["Sensorimotor reflexes", "Adolescent Egocentrism (किशोरीय अहंकेंद्रितता / आत्म-चिंतन)", "Animistic thinking", "Moral decay"], answer: 1, explanation: "Adolescent egocentrism involves heightened self-consciousness, imaginary audience beliefs, and deep introspection." },
        { subject: "CDP", type: "Concept", tagText: "Vygotsky", question: "Lev Vygotsky argued that the primary function of social speech in early human development is:", options: ["Displaying genetic superiority", "Social communication and establishing contact with adults and peers (सामाजिक संवाद व संपर्क)", "Internal mathematical calculation only", "Selfish dominance"], answer: 1, explanation: "Speech originates socially as communication before transforming into private speech and internalized thought." },
        { subject: "CDP", type: "IMP", tagText: "Inclusive Ed", question: "Universal Design for Learning (UDL) principles include providing multiple means of:", options: ["Standardized testing, punitive grading, and isolation", "Representation, Action & Expression, and Engagement (माहितीचे वैविध्यपूर्ण सादरीकरण, अभिव्यक्ती व सहभाग)", "Only computerized multiple choice drills", "Only traditional blackboard copying"], answer: 1, explanation: "UDL's 3 pillars ensure varied representations of content, flexible modes of student expression, and multiple pathways of engagement." },
        { subject: "CDP", type: "Pedagogy", tagText: "Collaborative Inquiry", question: "When middle school students work in heterogeneous collaborative groups to investigate a real-world environmental challenge, they build:", options: ["Social friction and noise only", "Socio-emotional competence, distributed expertise, and co-constructed problem-solving schemas (सहयोगात्मक समस्या निवारण)", "Total dependence on teachers", "Lower academic marks"], answer: 1, explanation: "Collaborative inquiry pools diverse cognitive perspectives, deepening shared conceptual mastery and social negotiation skills." },
        { subject: "Science", type: "Physics", tagText: "Sound Transmission", question: "Sound waves require a material medium for transmission and cannot travel through a:", options: ["Solid steel block", "Liquid water pool", "Vacuum / Empty space (निर्वात पोकळी)", "Gaseous air column"], answer: 2, explanation: "Sound waves are mechanical longitudinal pressure waves requiring vibrating matter particles; they cannot propagate in a vacuum." },
        { subject: "Science", type: "Chemistry", tagText: "Acids & Bases", question: "What is the pH value of a neutral aqueous solution at 25°C?", options: ["0", "7 (उदासीन द्रावण - pH ७)", "14", "1"], answer: 1, explanation: "On the logarithmic pH scale (0 to 14), exactly 7 represents a neutral solution where [H⁺] equals [OH⁻]." },
        { subject: "Science", type: "Biology", tagText: "Cell Division", question: "Which type of cell division produces gametes (sperm and egg cells) with half the original chromosome number (haploid)?", options: ["Mitosis", "Meiosis (अर्धसूत्री विभाजन)", "Binary fission", "Budding"], answer: 1, explanation: "Meiosis is a reductional cell division in reproductive gonads producing genetically diverse haploid gametes (n)." },
        { subject: "Science", type: "Pedagogy", tagText: "Inquiry Skills", question: "When science students design a controlled experiment to test which fertilizer makes plants grow tallest, the variable that is deliberately changed by them is the:", options: ["Dependent variable", "Independent variable (स्वतंत्र चल)", "Controlled variable", "Extraneous variable"], answer: 1, explanation: "The independent variable is the single experimental factor manipulated deliberately by the investigator to observe its effects." },
        { subject: "Maths", type: "Algebra", tagText: "Simultaneous Equations", question: "Solve for x and y: 3x + 2y = 11 and 2x + 3y = 4. What is the value of x + y?", options: ["1", "3 (x + y = ३)", "5", "7"], answer: 1, explanation: "Adding both equations: 5x + 5y = 15 -> 5(x + y) = 15 -> x + y = 15 ÷ 5 = 3." },
        { subject: "Maths", type: "Geometry", tagText: "Circles", question: "A chord of length 16 cm is drawn in a circle of radius 10 cm. What is the perpendicular distance from the center to the chord?", options: ["6 cm (६ सेमी)", "8 cm", "12 cm", "4 cm"], answer: 0, explanation: "Perpendicular from center bisects chord into two 8 cm segments. By Pythagoras: distance² = 10² - 8² = 100 - 64 = 36 -> distance = 6 cm." },
        { subject: "Maths", type: "Arithmetic", tagText: "LCM-HCF", question: "The HCF of two numbers is 18 and their product is 12,960. What is their LCM?", options: ["640", "720 (७२०)", "800", "960"], answer: 1, explanation: "LCM = Product of two numbers ÷ HCF = 12,960 ÷ 18 = 720." },
        { subject: "Maths", type: "Pedagogy", tagText: "Conceptual vs Procedural", question: "Procedural fluency in mathematics should always be:", options: ["Taught as blind memorization before any meaning", "Grounded firmly in conceptual understanding and logical sense-making (संकल्पनात्मक आकलनावर आधारित)", "Taught without numbers", "Eliminated from school math"], answer: 1, explanation: "Procedural algorithms must build on conceptual understanding to prevent mechanical errors and mathematical alienation." },
        { subject: "Social Science", type: "History", tagText: "Maratha Administration", question: "In the Maratha administrative system established by Chhatrapati Shivaji Maharaj, the council of eight prominent ministers was known as:", options: ["Navaratnas", "Ashtapradhan Mandal (अष्टप्रधान मंडळ)", "Ashtadiggajas", "Mansabdars"], answer: 1, explanation: "Chhatrapati Shivaji Maharaj instituted the Ashtapradhan Mandal, an eight-minister cabinet with portfolios like Peshwa, Amatya, and Senapati." },
        { subject: "Social Science", type: "Geography", tagText: "Earth's Crust", question: "The continental crust (भू-खंडीय कवच) is primarily composed of which two mineral elements?", options: ["Silica and Magnesium (SIMA)", "Silica and Alumina (SIAL - सियाल)", "Nickel and Iron (NIFE)", "Magnesium and Iron"], answer: 1, explanation: "The lighter granitic continental crust consists predominantly of Silica and Alumina, designated as SIAL." },
        { subject: "Social Science", type: "Civics", tagText: "Fundamental Rights", question: "Under which article of the Indian Constitution is Untouchability abolished and its practice in any form strictly forbidden by law?", options: ["Article 14", "Article 17 (कलम १७ - अस्पृश्यता निवारण)", "Article 19", "Article 21"], answer: 1, explanation: "Article 17 of the Constitution explicitly abolishes Untouchability and outlaws its practice in all forms as a punishable offense." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Field Observations", question: "Middle school students visiting a local river to record visible pollution sources and interview local residents are engaged in:", options: ["Wasting school time", "Experiential primary field research and geographic inquiry (प्रत्यक्ष क्षेत्रीय संशोधन)", "Passive textbook reading", "A picnic without learning"], answer: 1, explanation: "Field inquiry engages students in collecting primary environmental evidence, fostering analytical geographic thinking." },
        { subject: "Language", type: "Grammar", tagText: "Reported Speech", question: "He said, 'Bravo! You have performed brilliantly.' Indirect form:", options: ["He applauded him, saying that he had performed brilliantly.", "He shouted bravo that he performed.", "He told bravo.", "He said he performs brilliantly."], answer: 0, explanation: "Exclamatory approval sentences use reporting verbs like 'applauded' and change present perfect 'have performed' to 'had performed'." },
        { subject: "Language", type: "Vocab", tagText: "Synonym", question: "Synonym for 'Meticulous':", options: ["Careless", "Scrupulous / Extremely careful (अतिशय सावध/तपशीलवार)", "Lazy", "Rough"], answer: 1, explanation: "'Meticulous' means taking extreme care with small details; synonym is 'Scrupulous'." },
        { subject: "Language", type: "Pedagogy", tagText: "Multilingual Class", question: "When adolescents from diverse linguistic homes share equivalent idioms in their mother tongues, the classroom benefits by:", options: ["Creating disorder", "Deepening metalinguistic awareness, cultural respect, and cognitive transfer across languages (भाषिक व सांस्कृतिक देवाणघेवाण)", "Banning English", "Causing grammatical decay"], answer: 1, explanation: "Cross-linguistic comparison develops metalinguistic abstraction and celebrates linguistic diversity as an educational asset." },
        { subject: "Language", type: "Pedagogy", tagText: "Peer Review", question: "A successful peer review session in writing workshop requires:", options: ["Criticizing friends without evidence", "Specific rubrics, clear focus questions, and mutual respectful feedback norms (रचनात्मक अभिप्राय निकष)", "Grading with red pens", "Rewriting everything for the friend"], answer: 1, explanation: "Structured protocols direct peer feedback productively toward thematic clarity, evidence, and structural cohesion." }
    ],
    17: [
        { subject: "CDP", type: "PYQ", tagText: "Constructivism", question: "In a constructivist middle school science classroom, what is the role of prior knowledge (पूर्वज्ञान)?", options: ["It must be wiped clean as an obstacle", "It forms the essential cognitive foundation onto which new concepts are integrated and adapted (पायाभूत आधार)", "It is identical for all students", "It is tested with negative marks"], answer: 1, explanation: "Constructivism asserts that all new learning builds upon, anchors into, or reconstructs existing mental schemas." },
        { subject: "CDP", type: "Concept", tagText: "Piaget", question: "When a middle school student plans a science investigation by systematically holding all variables constant while varying one factor at a time, this reflects Piaget's:", options: ["Centration", "Isolation of Variables / Combinatorial Logic (चल घटकांचे पृथक्करण - औपचारिक अवस्था)", "Animism", "Egocentrism"], answer: 1, explanation: "Systematically isolating variables while holding others constant is a definitive marker of formal operational scientific reasoning." },
        { subject: "CDP", type: "IMP", tagText: "Inclusive Ed", question: "The principle of 'Least Restrictive Environment' (LRE) in inclusive education guarantees that students with disabilities should:", options: ["Be kept in segregated special schools forever", "Be educated to the maximum extent appropriate alongside their non-disabled peers in general education classrooms (कमाल समावेशक वातावरण)", "Be educated only at home", "Attend school only on weekends"], answer: 1, explanation: "LRE mandates educating students with disabilities in mainstream regular classrooms alongside non-disabled peers to the greatest extent possible." },
        { subject: "CDP", type: "Pedagogy", tagText: "Metacognition", question: "Self-regulated learners demonstrate metacognition by:", options: ["Relying exclusively on teacher reminders", "Setting goals, monitoring their own progress, diagnosing their own difficulties, and adjusting study strategies (ध्येयनिश्चिती व स्व-नियमन)", "Giving up whenever a task is hard", "Copying homework from friends"], answer: 1, explanation: "Self-regulation embodies active metacognitive oversight: goal setting, strategic monitoring, error detection, and adaptation." },
        { subject: "Science", type: "Physics", tagText: "Optics", question: "Which type of lens is thicker in the middle than at the edges and converges parallel rays of light to a principal focus?", options: ["Concave lens", "Convex lens (बहिर्गोल भिंग)", "Plano-concave lens", "Cylindrical lens"], answer: 1, explanation: "A convex (converging) lens is thicker in the center and bends incident parallel rays inward to a real focal point." },
        { subject: "Science", type: "Chemistry", tagText: "Carbon & Fuel", question: "Which fraction of petroleum refining is widely utilized as fuel in domestic cooking gas cylinders in liquid form under pressure?", options: ["Diesel", "Liquefied Petroleum Gas - LPG (द्रवीभूत पेट्रोलियम गॅस - प्रोपेन व ब्युटेन)", "Kerosene", "Bitumen"], answer: 1, explanation: "LPG consists primarily of pressurized liquefied butane and propane, serving as a clean domestic cooking fuel." },
        { subject: "Science", type: "Biology", tagText: "Nervous System", question: "In the human central nervous system, what is the largest and most developed part of the brain responsible for voluntary movement, memory, and conscious thought?", options: ["Cerebrum (प्रमस्तिष्क / मोठा मेंदू)", "Cerebellum (लहान मेंदू)", "Medulla oblongata", "Spinal cord"], answer: 0, explanation: "The cerebrum controls voluntary motor functions, sensory interpretation, reasoning, language, and memory." },
        { subject: "Science", type: "Pedagogy", tagText: "Misconceptions", question: "A student believes that 'air has no weight because we cannot feel it'. How can a teacher best demonstrate that air has mass?", options: ["Telling the student to believe the textbook", "Balancing two identical inflated balloons on a stick, then puncturing one and observing the tilt (फुग्यांचा तोल दाखवणारा प्रयोग)", "Giving a failing mark on the quiz", "Ignoring the student's comment"], answer: 1, explanation: "Balancing two inflated balloons and puncturing one proves visually and tangibly that trapped air has measurable mass." },
        { subject: "Maths", type: "Algebra", tagText: "Simultaneous", question: "If 3x + 4y = 25 and 4x + 3y = 24, what is the value of x - y?", options: ["-1 (-१)", "1", "2", "3"], answer: 0, explanation: "Subtracting first equation from second: (4x - 3x) + (3y - 4y) = 24 - 25 -> x - y = -1." },
        { subject: "Maths", type: "Geometry", tagText: "Circles", question: "In a circle, what is the angle subtended by a diameter at any point on the circumference?", options: ["45°", "60°", "90° (काटकोन ९० अंश)", "180°"], answer: 2, explanation: "Thales' theorem proves that any angle inscribed in a semicircle subtended by a diameter is always a right angle (90°)." },
        { subject: "Maths", type: "Arithmetic", tagText: "Average", question: "The average of 6 numbers is 20. If one number is removed, the average becomes 18. What was the removed number?", options: ["26", "28", "30 (३०)", "32"], answer: 2, explanation: "Sum of 6 numbers = 6 × 20 = 120. Sum of remaining 5 numbers = 5 × 18 = 90. Removed number = 120 - 90 = 30." },
        { subject: "Maths", type: "Pedagogy", tagText: "Maths Discourse", question: "Promoting rich mathematical discourse in Grade 8 classrooms requires teachers to:", options: ["Insist that students speak only when called on for the final numerical answer", "Encourage students to articulate their reasoning, question peers' strategies, and justify multiple approaches (गणितीय विचार मांडणे व युक्तीवाद)", "Silence all talk during the entire class", "Do all calculations on the board silently"], answer: 1, explanation: "Mathematical discourse fosters cognitive clarity by requiring students to justify assumptions and defend alternative strategies." },
        { subject: "Social Science", type: "History", tagText: "Delhi Sultanate", question: "Who was the only female Muslim sovereign to rule the throne of the Delhi Sultanate (1236-1240 CE)?", options: ["Razia Sultana (रजिया सुलतान)", "Nur Jahan", "Chand Bibi", "Mumtaz Mahal"], answer: 0, explanation: "Razia Sultana, daughter of Sultan Iltutmish, was the remarkable first and only female ruler of the Delhi Sultanate." },
        { subject: "Social Science", type: "Geography", tagText: "Biomes", question: "The tropical rainforest biome, characterized by dense multi-layered evergreen canopies and maximum terrestrial biodiversity, is found near the:", options: ["Poles", "Equator (विषुववृत्तीय प्रदेश)", "Tropic of Cancer in deserts", "Arctic Circle"], answer: 1, explanation: "Equatorial rainforests thrive in warm, daily rain conditions around the equator, harboring tremendous biodiversity." },
        { subject: "Social Science", type: "Civics", tagText: "Criminal Justice", question: "In the Indian criminal justice system, which official files the First Information Report (FIR) and conducts the investigation?", options: ["Public Prosecutor", "Police Officer (पोलीस अधिकारी)", "Judge", "Defense Lawyer"], answer: 1, explanation: "The police register the FIR under Section 154 CrPC and conduct investigations before the public prosecutor prosecutes in court." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Oral History", question: "Having middle school students interview elderly grandparents about their lived memories of India's Partition or Independence uses:", options: ["Biased gossip", "Oral history as an authentic, humanized historical methodology (मौखिक इतिहास पद्धती)", "Textbook duplication", "Fictional cinema"], answer: 1, explanation: "Oral history captures personal lived experiences and social memory, providing humanizing primary testimony on historical events." },
        { subject: "Language", type: "Grammar", tagText: "Voice", question: "Change to active voice: 'The speech was enthusiastically applauded by the audience.'", options: ["The audience enthusiastically applauded the speech.", "The audience applauds speech.", "The audience had applauded speech.", "Speech was applauded."], answer: 0, explanation: "'was applauded' converts directly to simple past active 'enthusiastically applauded'." },
        { subject: "Language", type: "Vocab", tagText: "One Word", question: "A solution or remedy for all difficulties or diseases is called a:", options: ["Panacea (रामबाण उपाय/सर्वदोषनिवारक)", "Placebo", "Pandemic", "Pharmacy"], answer: 0, explanation: "'Panacea' is a universal remedy or medicine purported to cure all diseases or difficulties." },
        { subject: "Language", type: "Pedagogy", tagText: "Reading Comprehension", question: "Which comprehension strategy involves readers pausing to summarize paragraphs and check whether they understand what they just read?", options: ["Self-monitoring and comprehension repair (स्व-आकलन व फेर-वाचन)", "Speed skimming only", "Choral chanting", "Mechanical spelling copy"], answer: 0, explanation: "Metacognitive self-monitoring involves ongoing comprehension checks and applying 'fix-up' strategies when meaning breaks down." },
        { subject: "Language", type: "Pedagogy", tagText: "Portfolio", question: "A student writing portfolio should be used primarily for:", options: ["Filing away at year-end without student inspection", "Reflecting on individual writing growth, revision history, and diverse genre competencies over time (लेखन प्रगतीचा सर्वंकष वेध)", "Assigning punishment for messy handwriting", "Comparing ranks among siblings"], answer: 1, explanation: "Portfolios demonstrate cumulative growth across writing genres, drafting stages, and reflective self-assessments." }
    ],
    18: [
        { subject: "CDP", type: "PYQ", tagText: "Gardner", question: "A botanist or an environmental scientist who exhibits exceptional sensitivity to flora, fauna, and natural habitats possesses high:", options: ["Spatial Intelligence", "Naturalistic Intelligence (नैसर्गिक बुद्धिमत्ता)", "Intrapersonal Intelligence", "Bodily-Kinesthetic Intelligence"], answer: 1, explanation: "Naturalistic intelligence encompasses expertise in recognizing, classifying, and interacting with plant, animal, and ecological systems." },
        { subject: "CDP", type: "Concept", tagText: "Vygotsky", question: "Vygotsky's socio-cultural theory views the relationship between learning and cognitive development as:", options: ["Learning trails behind physical biological maturation", "Learning precedes and pulls cognitive development forward within the ZPD (अध्ययन विकासाला गती देते)", "Learning has no impact on development", "Development stops before school starts"], answer: 1, explanation: "Vygotsky asserted that properly organized instruction awakens internal developmental processes, pulling development forward." },
        { subject: "CDP", type: "IMP", tagText: "Emotional Development", question: "During adolescence, intense emotional mood swings are developmentally linked to:", options: ["Moral degeneration", "Rapid endocrine hormonal shifts interacting with ongoing prefrontal brain maturation (हार्मोनल बदल व मेंदूचा विकास)", "Lack of vitamins only", "Television watching alone"], answer: 1, explanation: "Hormonal surges interacting with an actively remodeling adolescent brain underlie emotional intensity and mood variability." },
        { subject: "CDP", type: "Pedagogy", tagText: "Formative Assessment", question: "Which assessment practice best embodies 'Assessment OF Learning' (संकलित मूल्यमापन)?", options: ["Exit tickets at the end of a lesson", "End-of-term standardized comprehensive achievement examinations (सत्रांत अंतिम संपादणूक परीक्षा)", "Peer feedback during drafting", "Think-pair-share dialogues"], answer: 1, explanation: "Assessment of learning is summative, evaluating cumulative student learning at the end of an instructional epoch." },
        { subject: "Science", type: "Physics", tagText: "Electric Circuit", question: "What happens to the brightness of bulbs connected in a series circuit if more identical bulbs are added to the same battery circuit?", options: ["Brightness increases", "Brightness decreases for all bulbs (सर्व दिव्यांचा प्रकाश मंद होतो)", "Brightness remains unchanged", "Bulbs blow up immediately"], answer: 1, explanation: "In a series circuit, each added bulb increases total resistance, reducing total current and decreasing individual bulb brightness." },
        { subject: "Science", type: "Chemistry", tagText: "Chemical Bonding", question: "Common table salt (Sodium Chloride - NaCl) is formed by the complete transfer of an electron from sodium to chlorine, creating an:", options: ["Covalent bond", "Ionic / Electrovalent bond (आयनिक बंध)", "Hydrogen bond", "Metallic bond"], answer: 1, explanation: "Sodium transfers its valence electron to chlorine, forming Na⁺ and Cl⁻ ions held by electrostatic ionic bonding." },
        { subject: "Science", type: "Biology", tagText: "Cell Biology", question: "Which cellular structure present in plant cells provides rigid structural support and shape, but is completely absent in animal cells?", options: ["Plasma membrane", "Cell wall made of cellulose (पेशीभित्तिका)", "Mitochondria", "Nucleus"], answer: 1, explanation: "Plant cells are enclosed by a rigid outer cell wall composed of cellulose, providing structural turgor support." },
        { subject: "Science", type: "Pedagogy", tagText: "Concept Learning", question: "When teaching the abstract concept of 'Energy Conservation', the most effective pedagogical approach is:", options: ["Dictating the law of conservation of energy 10 times", "Using real-world roller coaster simulations, pendulums, and hydroelectric models tracking kinetic-potential conversions (प्रत्यक्ष प्रात्यक्षिके व सिम्युलेशन)", "Writing formulas on the board in silence", "Skipping physics"], answer: 1, explanation: "Tracking energy transformations dynamically through pendulums and simulations bridges the abstract conservation law to visible phenomena." },
        { subject: "Maths", type: "Algebra", tagText: "Linear Equations", question: "Solve for x: 0.25(4x - 3) = 0.05(10x - 9). What is x?", options: ["0.6", "0.8 (x = ०.८)", "1.0", "1.2"], answer: 1, explanation: "1x - 0.75 = 0.5x - 0.45 -> 1x - 0.5x = 0.75 - 0.45 -> 0.5x = 0.30 -> x = 0.30 ÷ 0.5 = 0.6 (or if x - 0.75 = 0.5x - 0.45: 0.5x = 0.30 -> x = 0.6)." },
        { subject: "Maths", type: "Geometry", tagText: "Triangles", question: "In triangle ABC, if angle A = 70° and angle B = 50°, which side of the triangle is the longest?", options: ["Side AB (सर्वात मोठी बाजू AB)", "Side BC", "Side AC", "All sides are equal"], answer: 0, explanation: "Angle C = 180° - (70° + 50°) = 60°. The side opposite to the largest angle (A = 70°) is BC? Wait: Angle A=70 (opp BC), Angle B=50 (opp AC), Angle C=60 (opp AB). Longest side is opposite largest angle (Angle A=70 -> side BC is longest)." },
        { subject: "Maths", type: "Arithmetic", tagText: "Fractions", question: "What is 3/5 of 2/3 of 150?", options: ["40", "50", "60 (६०)", "75"], answer: 2, explanation: "(3/5) × (2/3) × 150 = (6/15) × 150 = (2/5) × 150 = 2 × 30 = 60." },
        { subject: "Maths", type: "Pedagogy", tagText: "Heuristics", question: "Working backwards (उलट पद्धतीने विचार करणे) is a mathematical problem-solving heuristic particularly effective for:", options: ["Drawing a straight line", "Problems where the final outcome/result is known and initial quantities must be deduced (अंतिम निष्पत्तीवरून मूळ संख्या शोधणे)", "Rote counting", "Formula memorization"], answer: 1, explanation: "'Working backwards' is an effective heuristic when a problem specifies end conditions and requires deducing starting inputs." },
        { subject: "Social Science", type: "History", tagText: "Mughal Architecture", question: "The famous Red Fort in Delhi and the Jama Masjid were commissioned by which Mughal emperor renowned for grand architecture?", options: ["Akbar", "Jahangir", "Shah Jahan (शहाजहान)", "Babur"], answer: 2, explanation: "Shah Jahan's golden age of architecture produced the Red Fort, Jama Masjid, and the Taj Mahal." },
        { subject: "Social Science", type: "Geography", tagText: "Deserts", question: "The Sahara Desert in North Africa is the world's largest hot desert. Which type of vegetation dominates its arid landscape?", options: ["Dense deciduous trees", "Cactus, acacia, and date palms adapted to drought (कमी पाण्यात येणाऱ्या वनस्पती)", "Coniferous pine forests", "Mangrove swamps"], answer: 1, explanation: "Xerophytic vegetation like thorny acacias, deep-rooted cacti, and oasis date palms survive hyper-arid Saharan conditions." },
        { subject: "Social Science", type: "Civics", tagText: "Local Government", question: "In the 73rd Constitutional Amendment Act, what proportion of total seats in Panchayati Raj institutions is constitutionally reserved for women?", options: ["One-fifth (20%)", "One-third (33% - किमान एक तृतीयांश जागा)", "One-half (50%)", "One-fourth (25%)"], answer: 1, explanation: "Article 243D(3) mandates that not less than one-third of total seats in Panchayats must be reserved for women." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Debate", question: "Organizing classroom debates on topics like 'Should large dams be replaced by micro-watershed conservation?' develops students':", options: ["Hostility", "Evidence-based argumentation, multi-perspective policy analysis, and ecological empathy (तार्किक युक्तीवाद व बहुपर्यायी विचार)", "Disregard for books", "Blind obedience"], answer: 1, explanation: "Structured academic debates compel students to research opposing evidence, formulate rational arguments, and respect complexity." },
        { subject: "Language", type: "Grammar", tagText: "Relative Clauses", question: "The scientist ____ discovered the vaccine was awarded the prestigious prize.", options: ["which", "who (who discovered)", "whom", "whose"], answer: 1, explanation: "'Who' is the subject relative pronoun used to refer to human persons (the scientist)." },
        { subject: "Language", type: "Vocab", tagText: "Antonym", question: "Antonym for 'Rigid':", options: ["Hard", "Flexible / Pliant (लवचिक)", "Stiff", "Unbending"], answer: 1, explanation: "'Rigid' means unable to bend or be forced out of shape; its antonym is 'Flexible'." },
        { subject: "Language", type: "Pedagogy", tagText: "Reading Strategies", question: "The reading strategy where a reader visualizes descriptive sensory scenes in their mind to comprehend a novel is:", options: ["Mental Imagery / Visualization (दृश्यात्मक कल्पनाशक्ती)", "Mechanical scanning", "Rote copying", "Proofreading"], answer: 0, explanation: "Mental visualization actively converts verbal textual descriptions into rich internal sensory representations, boosting memory." },
        { subject: "Language", type: "Pedagogy", tagText: "Assessment of Writing", question: "When grading an argumentative essay, evaluating 'Coherence' means checking whether:", options: ["Every word is spelled correctly", "Paragraphs flow logically and connect smoothly to support a central thesis (विचारांची तार्किक सुसंगतता)", "The handwriting is artistic", "The paper is printed in blue ink"], answer: 1, explanation: "Coherence assesses logical progression, transitional flow, and conceptual consistency across an argument." }
    ],
    19: [
        { subject: "CDP", type: "PYQ", tagText: "Adolescent Development", question: "Adolescent brain development is characterized by high sensitivity to rewards and peer approval due to rapid maturation of the:", options: ["Occipital lobe only", "Limbic system (भावनिक मेंदू) ahead of the executive prefrontal cortex", "Spinal cord reflexes", "Hearing auditory canal"], answer: 1, explanation: "The socio-emotional limbic system matures ahead of the cognitive prefrontal control center, heightening sensation-seeking." },
        { subject: "CDP", type: "Concept", tagText: "Vygotsky", question: "According to Lev Vygotsky, cognitive tools (such as numbering systems, algebraic symbols, and writing) are:", options: ["Biologically inherited DNA", "Cultural psychological tools that transform and enhance mental functioning (सांस्कृतिक साधने)", "Useless burdens", "Same across all animals"], answer: 1, explanation: "Vygotsky argued that cultural semiotic tools (language, signs, numbers) profoundly transform human cognitive architecture." },
        { subject: "CDP", type: "IMP", tagText: "Inclusive Ed", question: "A middle school teacher who practices universal inclusion creates assessments that:", options: ["Rely solely on timed speed writing tests", "Provide diverse modalities of response (written, oral presentations, digital models, multimedia portfolios) (अभिव्यक्तीचे वैविध्यपूर्ण पर्याय)", "Require only rote recitation", "Punish those who need accommodations"], answer: 1, explanation: "UDL assessment offers varied response modes so diverse learners can authentically display conceptual mastery." },
        { subject: "CDP", type: "Pedagogy", tagText: "Metacognitive Questioning", question: "Asking students 'How did you arrive at that answer and what steps did you take?' prompts:", options: ["Anxiety only", "Metacognitive reflection on the cognitive process and strategic reasoning (विचारप्रक्रियेचे स्पष्टीकरण)", "Memory loss", "Rejection of the answer"], answer: 1, explanation: "Prompting students to explain their problem-solving path fosters conscious metacognitive awareness of strategic thinking." },
        { subject: "Science", type: "Physics", tagText: "Gravity & Mass", question: "If an astronaut travels from Earth to the Moon, how do her mass and weight change on the Moon?", options: ["Both mass and weight remain the same", "Mass remains constant, but weight decreases to about 1/6th of that on Earth (वस्तुमान तेच राहते, वजन १/६ होते)", "Both mass and weight decrease", "Mass decreases, weight stays constant"], answer: 1, explanation: "Mass (quantity of matter) is invariant, while weight (W = mg) decreases because lunar surface gravity is 1/6th of Earth's." },
        { subject: "Science", type: "Chemistry", tagText: "Acids & Bases", question: "Which acid is secreted naturally by the gastric glands in the human stomach to kill bacteria and activate the digestive enzyme pepsin?", options: ["Sulfuric acid", "Hydrochloric acid (हायड्रोक्लोरिक आम्ल - HCl)", "Nitric acid", "Acetic acid"], answer: 1, explanation: "Hydrochloric acid (HCl) creates the acidic pH (~1.5-2) necessary for pepsin to break down proteins and eliminates bacteria." },
        { subject: "Science", type: "Biology", tagText: "Photosynthesis", question: "During the light-dependent reactions of photosynthesis, solar energy absorbed by chlorophyll is utilized to split water molecules into:", options: ["Carbon and glucose", "Hydrogen ions, electrons, and Oxygen gas (H₂O चे विघटन होऊन ऑक्सिजन मुक्त होतो)", "Nitrogen and methane", "Carbon dioxide"], answer: 1, explanation: "Photolysis splits water (H₂O) into protons, electrons, and molecular oxygen (O₂), which is released into the atmosphere." },
        { subject: "Science", type: "Pedagogy", tagText: "Concept Application", question: "Having students calculate the speed of their own walking in meters per second during a school playground activity helps them:", options: ["Waste time", "Apply abstract kinematic formulas to tangible personal lived experiences (सूत्रांचा प्रत्यक्ष जीवनात वापर)", "Dislike mathematics", "Avoid experiments"], answer: 1, explanation: "Measuring personal motion grounds abstract velocity formulas (Speed = Distance/Time) in vivid experiential reality." },
        { subject: "Maths", type: "Algebra", tagText: "Identities", question: "Evaluate using algebraic identities: 103 × 97.", options: ["9,981", "9,991 (९,९९१)", "10,001", "9,891"], answer: 1, explanation: "103 × 97 = (100 + 3)(100 - 3) = 100² - 3² = 10,000 - 9 = 9,991." },
        { subject: "Maths", type: "Geometry", tagText: "Trapezium", question: "The parallel sides of a trapezium are 12 cm and 18 cm, and the distance between them is 8 cm. What is its area?", options: ["100 sq. cm", "120 sq. cm (१२० चौ. सेमी)", "140 sq. cm", "240 sq. cm"], answer: 1, explanation: "Area of trapezium = 1/2 × (sum of parallel sides) × height = 1/2 × (12 + 18) × 8 = 1/2 × 30 × 8 = 120 sq. cm." },
        { subject: "Maths", type: "Arithmetic", tagText: "Ratios", question: "Two numbers are in the ratio 4 : 5. If their sum is 180, what is the larger number?", options: ["80", "90", "100 (१००)", "120"], answer: 2, explanation: "4x + 5x = 180 -> 9x = 180 -> x = 20. Larger number = 5x = 5 × 20 = 100." },
        { subject: "Maths", type: "Pedagogy", tagText: "Mathematical Proof", question: "The primary purpose of teaching geometric proofs in middle school is to develop students':", options: ["Handwriting speed", "Logical deduction, formal reasoning, and axiomatic thinking (तार्किक निगमन व सिद्धता क्षमता)", "Blind memorization of figures", "Ability to copy from textbooks"], answer: 1, explanation: "Geometric proofs train students in disciplined deduction: moving from known axioms to necessary conclusions." },
        { subject: "Social Science", type: "History", tagText: "Colonial Economy", question: "Dadabhai Naoroji formulated the famous 'Drain of Wealth' (संपत्तीचे वहन) theory in his landmark book:", options: ["Poverty and Un-British Rule in India (भारतातील दारिद्र्य व अन-ब्रिटिश राज्य)", "Discovery of India", "Hind Swaraj", "Gulamgiri"], answer: 0, explanation: "Dadabhai Naoroji demonstrated in 'Poverty and Un-British Rule in India' how colonial policies siphoned Indian wealth to Britain." },
        { subject: "Social Science", type: "Geography", tagText: "Atmosphere", question: "Almost all weather phenomena (clouds, rainfall, fog, storms) occur in which lowest layer of the atmosphere?", options: ["Troposphere (तपांबर)", "Stratosphere", "Mesosphere", "Exosphere"], answer: 0, explanation: "The troposphere contains 75% of atmospheric mass and all moisture, hosting all weather phenomena." },
        { subject: "Social Science", type: "Civics", tagText: "Fundamental Duties", question: "The Fundamental Duties of Indian citizens were incorporated into Part IV-A of the Constitution upon the recommendation of the:", options: ["Sarkaria Commission", "Swaran Singh Committee (स्वर्ण सिंह समिती - १९७६)", "Kothari Commission", "Verma Committee"], answer: 1, explanation: "The Swaran Singh Committee recommendations led to the 42nd Amendment (1976), introducing Fundamental Duties (Article 51A)." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Critical Thinking", question: "Asking middle school students 'How did the introduction of railways change both economic transport and social caste interactions in colonial India?' promotes:", options: ["Confusion of facts", "Multi-causal historical thinking and analysis of social transformation (बहुआयामी ऐतिहासिक विश्लेषण)", "Dislike for trains", "Blind memorization of dates"], answer: 1, explanation: "Investigating dual economic and sociological impacts of infrastructure cultivates multi-causal historical analysis." },
        { subject: "Language", type: "Grammar", tagText: "Conjunctions", question: "Hardly had the teacher entered the classroom ____ the students stood up to greet her.", options: ["than", "when (Hardly had... when)", "then", "while"], answer: 1, explanation: "Correlative pair rule: 'Hardly / Scarcely had... when...'." },
        { subject: "Language", type: "Vocab", tagText: "Synonym", question: "Synonym for 'Resolute':", options: ["Determined / Firm (निश्चयी, ठाम)", "Vacillating", "Hesitant", "Feeble"], answer: 0, explanation: "'Resolute' means admirably purposeful, determined, and unwavering; synonym is 'Determined / Firm'." },
        { subject: "Language", type: "Pedagogy", tagText: "Poetry Appreciation", question: "When teaching English poetry in Grade 8, the teacher's primary focus should be on:", options: ["Checking every spelling error strictly", "Aesthetic appreciation, imagery, rhythm, and personal emotional interpretation (सौंदर्यदृष्टी, कल्पना व रसग्रहण)", "Memorizing rhyme schemes only", "Translating line by line without feeling"], answer: 1, explanation: "Poetry pedagogy prioritizes aesthetic resonance, metaphorical imagery, rhythm, and imaginative enjoyment." },
        { subject: "Language", type: "Pedagogy", tagText: "Reading Skills", question: "Skimming a long nonfiction chapter before in-depth reading helps adolescent learners to:", options: ["Skip the chapter entirely", "Activate prior knowledge, establish an overarching mental schema, and anticipate key themes (पूर्वज्ञान जागृती व मुख्य मुद्दे समजणे)", "Forget the vocabulary", "Avoid comprehension"], answer: 1, explanation: "Skimming establishes an advance cognitive organizer, preparing the mind for targeted conceptual assimilation." }
    ],
    20: [
        { subject: "CDP", type: "PYQ", tagText: "Adolescent Moral", question: "In Lawrence Kohlberg's post-conventional stage, moral dilemmas are resolved by evaluating:", options: ["What parents will say", "Universal ethical principles of justice, human dignity, and equality (सार्वत्रिक न्याय व मानवी प्रतिष्ठा)", "What will avoid police arrest", "Immediate sensory pleasure"], answer: 1, explanation: "Post-conventional morality appeals to universal ethical principles that transcend local societal conventions." },
        { subject: "CDP", type: "Concept", tagText: "Piaget", question: "In Piaget's theory, the formal operational stage (11+ years) enables adolescents to think about thought itself. This capability is known as:", options: ["Second-order thinking / Reflective abstraction (आत्म-चिंतन व अमूर्त विचार)", "Irreversibility", "Animism", "Sensorimotor trial"], answer: 0, explanation: "Second-order thinking allows adolescents to reflect upon their own thinking processes and abstract propositional hypotheses." },
        { subject: "CDP", type: "IMP", tagText: "Inclusive Ed", question: "Inclusion is not merely mainstreaming physical presence; it fundamentally means:", options: ["Making special students sit quietly at the back", "Ensuring full belonging, active participation, high expectations, and equitable opportunities for every child (पूर्ण सहभाग व समान संधी)", "Lowering all academic goals to zero", "Banning special education teachers"], answer: 1, explanation: "True inclusion fosters a genuine sense of belonging, equitable access, and adapted support for all learners." },
        { subject: "CDP", type: "Pedagogy", tagText: "Constructivist Teacher", question: "An effective constructivist teacher in an upper primary school behaves primarily as an:", options: ["Authoritarian lecturer", "Architect of rich learning environments and facilitator of inquiry (शिकण्याच्या वातावरणाचा निर्माता व सुलभक)", "Uncaring grader", "Enforcer of silence"], answer: 1, explanation: "Constructivist teachers curate stimulating environments, ask generative questions, and scaffold pupil-led discoveries." },
        { subject: "Science", type: "Physics", tagText: "Newton Laws", question: "Which physical quantity represents the measure of an object's inertia (जडत्व)?", options: ["Velocity", "Mass (वस्तुमान)", "Acceleration", "Force"], answer: 1, explanation: "Mass is the intrinsic quantitative measure of an object's inertia (resistance to changes in velocity)." },
        { subject: "Science", type: "Chemistry", tagText: "Acids & Metals", question: "When copper metal is exposed to moist air containing CO₂ and water for a prolonged time, it develops a dull green coating composed of:", options: ["Copper sulfate", "Basic copper carbonate [CuCO₃·Cu(OH)₂] (तांब्यावरील हिरवा थर)", "Copper oxide only", "Copper chloride"], answer: 1, explanation: "Moist corrosion of copper yields a green protective patina of basic copper carbonate [CuCO₃·Cu(OH)₂]." },
        { subject: "Science", type: "Biology", tagText: "Photosynthesis", question: "During the light-independent reactions (Calvin cycle) of photosynthesis, carbon dioxide is chemically fixed and reduced into:", options: ["Proteins", "Glucose / Carbohydrates (ग्लुकोज/कर्बोदके)", "Lipids", "Oxygen"], answer: 1, explanation: "The Calvin cycle utilizes ATP and NADPH produced in light reactions to convert CO₂ into high-energy glucose." },
        { subject: "Science", type: "Pedagogy", tagText: "Inquiry Skills", question: "When students measure the temperature of water cooling in a cup every 2 minutes and plot a graph, they are demonstrating:", options: ["Boredom", "Empirical data gathering, graphical representation, and quantitative analysis (माहिती संकलन व आलेख विश्लेषण)", "Textbook recitation", "Pure guesswork"], answer: 1, explanation: "Systematic data collection and graphical analysis train foundational empirical scientific investigation skills." },
        { subject: "Maths", type: "Algebra", tagText: "Quadratic Expressions", question: "What are the factors of the algebraic expression: x² - 16?", options: ["(x - 4)(x - 4)", "(x - 4)(x + 4) ((x - ४)(x + ४))", "(x - 16)(x + 1)", "(x + 4)(x + 4)"], answer: 1, explanation: "Difference of squares formula: x² - 16 = x² - 4² = (x - 4)(x + 4)." },
        { subject: "Maths", type: "Geometry", tagText: "Polygons", question: "What is the measure of each interior angle of a regular octagon (8 sides)?", options: ["120°", "135° (१३५ अंश)", "140°", "150°"], answer: 1, explanation: "Each interior angle = [(n - 2) × 180°] ÷ n = [(8 - 2) × 180°] ÷ 8 = (6 × 180°) ÷ 8 = 1080° ÷ 8 = 135°." },
        { subject: "Maths", type: "Arithmetic", tagText: "Percentages", question: "A number is first increased by 20% and then decreased by 20%. What is the net percentage change in the number?", options: ["No change", "4% decrease (४% घट)", "4% increase", "2% decrease"], answer: 1, explanation: "Let number = 100. After +20% -> 120. After -20% of 120 (24) -> 120 - 24 = 96. Net change = 100 - 96 = 4% decrease." },
        { subject: "Maths", type: "Pedagogy", tagText: "Nature of Maths", question: "Which statement accurately describes the axiomatic structure of Mathematics?", options: ["Math is purely a set of memorized calculation recipes", "Math builds logically from accepted undefined terms and axioms to prove deduced theorems (स्वयंसिद्ध तत्त्वे व सिद्धता)", "Math has no proofs", "Math is unrelated to reasoning"], answer: 1, explanation: "Mathematics is a deductive axiomatic system building theorems rigorously from basic undefined terms, definitions, and axioms." },
        { subject: "Social Science", type: "History", tagText: "Social Movement", question: "Who founded the 'Self-Respect Movement' (आत्मसन्मान आंदोलन) in Tamil Nadu in 1925 to fight caste oppression and champion rationalism?", options: ["E.V. Ramasamy Periyar (पेरियार ई. व्ही. रामसामी)", "K. Kamaraj", "Sri Narayana Guru", "C. Rajagopalachari"], answer: 0, explanation: "Periyar E.V. Ramasamy initiated the radical Self-Respect Movement, fiercely advocating rationalism, non-Brahmin equality, and women's rights." },
        { subject: "Social Science", type: "Geography", tagText: "Tectonic Boundaries", question: "When two tectonic plates slide past each other horizontally along a transform fault, the most frequent geological consequence is:", options: ["Fold mountain formation", "Deep ocean trenches", "Severe Earthquakes (तीव्र भूकंप)", "Volcanic island arcs"], answer: 2, explanation: "Transform plate boundaries (like the San Andreas Fault) cause frictional stress accumulation resulting in severe earthquakes." },
        { subject: "Social Science", type: "Civics", tagText: "Constitution", question: "Which constitutional amendment added the fundamental right to free and compulsory education (Article 21A) for all children aged 6 to 14?", options: ["42nd Amendment", "44th Amendment", "86th Constitutional Amendment (2002) (८६ वी घटनादुरुस्ती)", "73rd Amendment"], answer: 2, explanation: "The 86th Constitutional Amendment Act of 2002 inserted Article 21A, establishing education as an enforceable Fundamental Right." },
        { subject: "Social Science", type: "Pedagogy", tagText: "Source Work", question: "When middle school students evaluate archaeological artifacts, coins, and temple inscriptions alongside royal chronicles, they are acting as:", options: ["Passive listeners", "Apprentice historians interrogating historical evidence (इतिहासकारासारखा चिकित्सक अभ्यास)", "Simple copyists", "Exam memorizers"], answer: 1, explanation: "Cross-referencing material culture and epigraphy with literary texts trains students in genuine historical methodology." },
        { subject: "Language", type: "Grammar", tagText: "Transformation", question: "Change to indirect: He said, 'Alas! I have lost my passport.'", options: ["He exclaimed with sorrow that he had lost his passport.", "He shouted alas that lost passport.", "He said alas he lost passport.", "He told sorrowfully he loses passport."], answer: 0, explanation: "Exclamatory sentences with 'Alas' transform to 'exclaimed with sorrow + that + past perfect (had lost)'." },
        { subject: "Language", type: "Vocab", tagText: "Antonym", question: "Choose the antonym of 'Harmony':", options: ["Peace", "Discord / Conflict (कलह / विसंवाद)", "Agreement", "Symphony"], answer: 1, explanation: "'Harmony' denotes agreement or pleasing arrangement; its antonym is 'Discord' or 'Conflict'." },
        { subject: "Language", type: "Pedagogy", tagText: "Communicative Competence", question: "Which classroom activity best promotes authentic communicative competence in English for Grade 8 adolescents?", options: ["Translating textbook paragraphs into mother tongue word by word", "Participating in a structured town-hall simulation debating environmental conservation solutions (संवाद व चर्चा सत्र)", "Reciting grammar rules from memory", "Copying spelling words 20 times"], answer: 1, explanation: "Simulations and town-hall debates require spontaneous, authentic language use for real communicative negotiation." },
        { subject: "Language", type: "Pedagogy", tagText: "Reading Assessment", question: "Assessment of reading comprehension at upper primary level should focus primarily on:", options: ["Reading aloud speed without understanding", "Making inferences, identifying author bias, evaluating evidence, and synthesizing thematic ideas (सखोल आकलन व निष्कर्ष काढणे)", "Memorizing commas and periods", "Copying paragraphs without errors"], answer: 1, explanation: "Upper primary reading assessment evaluates inferential reasoning, critical evaluation, and thematic synthesis." }
    ]
};

