    { subject: "Language", type: "Grammar", tagText: "Clauses", question: "Identify the underlined clause: 'The student *who topped the exam* received a scholarship.'", options: ["Defining Relative / Adjective Clause", "Noun Clause", "Adverb Clause of Manner", "Adverb Clause of Degree"], answer: 0, explanation: "The clause modifies and identifies the noun 'student', functioning as an Adjective/Relative Clause." },
    { subject: "Language", type: "Vocabulary", tagText: "Idioms", question: "What does the idiom 'Bite the bullet' mean?", options: ["To face a grim or unavoidable situation with courage (संकटाला धैर्याने सामोरे जाणे)", "To shoot a firearm", "To eat quickly", "To surrender in battle"], answer: 0, explanation: "'Bite the bullet' means to endure a painful or unavoidable situation that one has been putting off." },
    { subject: "Language", type: "Grammar", tagText: "Conjunctions", question: "Fill in the blank: 'Not only did she win the gold medal, ____ she set a new world record.'", options: ["but also", "and also", "as well", "too"], answer: 0, explanation: "'Not only... but also' is a correlative conjunction pair used to link two parallel emphatic clauses." },
    { subject: "Language", type: "Pedagogy", tagText: "Literature in Language Teaching", question: "Integrating short stories and drama in middle school English classes primarily aims to:", options: ["Foster aesthetic sensitivity, critical interpretation, and emotional empathy through rich language", "Provide spelling test lists", "Substitute for history textbooks", "Eliminate grammar teaching entirely"], answer: 0, explanation: "Literature exposes learners to rich authentic language, diverse perspectives, and emotional and aesthetic depth." }
