    { subject: "CDP", type: "Assessment", tagText: "Summative Assessment", question: "Summative assessment is conducted primarily to:", options: ["Evaluate learning outcomes and certify achievement at the conclusion of an instructional period", "Diagnose daily misconceptions", "Guide day-to-day lesson adjustments", "Select classroom seat arrangements"], answer: 0, explanation: "Summative assessments evaluate cumulative achievement against predefined standards at the end of a course or term." },
    { subject: "Maths/Sci", type: "Arithmetic", tagText: "Direct and Inverse Proportion", question: "If 15 workers can build a wall in 48 hours, how many hours will 30 workers take to build the same wall?", options: ["24 hours", "96 hours", "36 hours", "12 hours"], answer: 0, explanation: "Inverse proportion: Workers × Time = Constant. 15 × 48 = 30 × T => T = (15 × 48) / 30 = 24 hours." },
    { subject: "Maths/Sci", type: "Geometry", tagText: "Circle Properties", question: "The perpendicular drawn from the center of a circle to a chord always:", options: ["Bisects the chord (जीवेचे समद्विभाजन करतो)", "Triples the chord", "Equals the radius", "Doubles the diameter"], answer: 0, explanation: "Geometric theorem: The perpendicular dropped from the center of a circle to any chord bisects that chord into two equal halves." },
    { subject: "Maths/Sci", type: "Physics", tagText: "Work Done", question: "In physics, work done is zero when the angle between the applied force and the displacement is:", options: ["90° (लंबरूप / काटकोन - cos 90° = 0)", "0°", "180°", "45°"], answer: 0, explanation: "Work = F · s · cos θ. When θ = 90° (e.g. a coolie carrying luggage on his head walking horizontally), work done by gravity is zero." },
    { subject: "Maths/Sci", type: "Chemistry", tagText: "Combustion", question: "Which zone of a candle flame is the hottest and is used by goldsmiths to melt gold and silver?", options: ["Non-luminous outer zone (निळा बाह्य भाग - संपूर्ण ज्वलन)", "Luminous middle zone", "Dark inner zone", "Lowest blue wick zone"], answer: 0, explanation: "The outermost non-luminous zone undergoes complete combustion with excess oxygen, making it the hottest region (~1400°C)." },
    { subject: "Maths/Sci", type: "Biology", tagText: "Human Circulatory System", question: "Which blood vessels carry oxygenated blood away from the heart to all body tissues?", options: ["Arteries (धमण्या / रोहिणी)", "Veins", "Capillaries", "Vena Cava"], answer: 0, explanation: "Arteries carry oxygenated blood under high pressure away from the heart to tissues (the pulmonary artery is the exception)." },
    { subject: "Social Science", type: "History", tagText: "Mughal Architecture", question: "The iconic Buland Darwaza at Fatehpur Sikri was commissioned by Akbar to commemorate his victory over:", options: ["Gujarat (गुजरात विजय)", "Bengal", "Kashmir", "Deccan"], answer: 0, explanation: "Emperor Akbar constructed the magnificent 54-meter Buland Darwaza ('Gate of Magnificence') in 1601 to celebrate his conquest of Gujarat." },
    { subject: "Social Science", type: "History", tagText: "Social Reform", question: "Who founded the 'Arya Samaj' in Bombay in 1875 with the motto 'Back to the Vedas'?", options: ["Swami Dayanand Saraswati (स्वामी दयानंद सरस्वती)", "Swami Vivekananda", "Raja Ram Mohan Roy", "Ishwar Chandra Vidyasagar"], answer: 0, explanation: "Swami Dayanand Saraswati founded the Arya Samaj, advocating Vedic philosophy, rejection of idol worship, and social reforms." },
    { subject: "Social Science", type: "Civics", tagText: "Lok Sabha Speaker", question: "Who presides over the joint sitting of both houses of the Indian Parliament?", options: ["Speaker of the Lok Sabha (लोकसभा अध्यक्ष)", "President of India", "Chairman of the Rajya Sabha (Vice President)", "Prime Minister"], answer: 0, explanation: "Under Article 118(4), the Speaker of the Lok Sabha presides over a joint sitting of Parliament summoned by the President." },
    { subject: "Social Science", type: "Civics", tagText: "Constitutional Remedies", question: "Which writ is issued by the Supreme Court or High Court to command a public official to perform their statutory public duty?", options: ["Mandamus (परमादेश)", "Habeas Corpus", "Quo Warranto", "Certiorari"], answer: 0, explanation: "The writ of Mandamus ('We command') compels a public official or lower body to perform a mandatory statutory legal duty." },
    { subject: "Social Science", type: "Geography", tagText: "Rock Cycle", question: "Which type of rocks are formed through the cooling and solidification of molten magma or lava?", options: ["Igneous Rocks (अग्निजन्य खडक)", "Sedimentary Rocks", "Metamorphic Rocks", "Fossiliferous Rocks"], answer: 0, explanation: "Igneous rocks (e.g. basalt, granite) crystallize directly from cooling magma or lava, forming primary crustal rocks." },
    { subject: "Language", type: "Pedagogy", tagText: "Communicative Language Teaching", question: "The primary theoretical foundation of Communicative Language Teaching (CLT) is based on:", options: ["Dell Hymes' concept of 'Communicative Competence'", "Skinner's Operant Conditioning", "Bloom's Psychomotor Taxonomy", "Gutenberg's typography"], answer: 0, explanation: "Dell Hymes formulated 'Communicative Competence'—knowing when, where, and how to use language appropriately in social context." },
    { subject: "Language", type: "Grammar", tagText: "Conjunctions", question: "Choose the correct conjunction: 'He worked day and night ____ he might clear the competitive exam.'", options: ["so that", "unless", "although", "lest"], answer: 0, explanation: "'So that' expresses purpose or goal, followed by a modal ('so that he might clear')." },
    { subject: "Language", type: "Vocabulary", tagText: "Synonym", question: "Synonym for 'Sagacious':", options: ["Wise and insightful (सुजाण/ज्ञानी/दूरदृष्टी असलेला)", "Foolish", "Ignorant", "Careless"], answer: 0, explanation: "'Sagacious' means having or showing keen mental discernment and good judgment; wise." },
    { subject: "Language", type: "Grammar", tagText: "Subject Verb Agreement", question: "Select the correct verb: 'Neither the principal nor the teachers ____ present at the ceremony.'", options: ["were", "was", "is", "has been"], answer: 0, explanation: "With correlative 'neither... nor', the verb agrees with the closer plural subject 'teachers' ('were present')." },
    { subject: "Language", type: "Pedagogy", tagText: "Task-Based Learning", question: "In Task-Based Language Teaching (TBLT), a 'task' is an activity where learners:", options: ["Use language authentically to achieve a meaningful communicative outcome", "Translate a 20-line paragraph word for word", "Recite verb conjugations in unison", "Fill in isolated prepositions on worksheets"], answer: 0, explanation: "A task requires real-world communicative language processing to solve problems, make decisions, or produce concrete outcomes." }
