    { subject: "Social Science", type: "History", tagText: "Social Reformers", question: "Who founded the 'Satyashodhak Samaj' in 1873 to liberate the lower castes from socio-religious exploitation?", options: ["Mahatma Jyotirao Phule (महात्मा जोतीराव फुले)", "Dr. B. R. Ambedkar", "Rajarshi Chhatrapati Shahu Maharaj", "Gopal Ganesh Agarkar"], answer: 0, explanation: "Mahatma Jyotirao Phule established the Satyashodhak Samaj in Pune on September 24, 1873, advocating social equity and education." },
    { subject: "Social Science", type: "Civics", tagText: "Right to Education", question: "Which Constitutional Amendment Act made the Right to Education a Fundamental Right under Article 21A for children aged 6 to 14?", options: ["86th Amendment Act (2002 - ८६ वी घटनादुरुस्ती)", "42nd Amendment Act", "44th Amendment Act", "91st Amendment Act"], answer: 0, explanation: "The 86th Amendment Act of 2002 inserted Article 21A, guaranteeing free and compulsory education as a fundamental right." },
    { subject: "Social Science", type: "Civics", tagText: "Independent Judiciary", question: "The independence of the Indian Judiciary is institutionally secured by which constitutional safeguard?", options: ["Security of tenure and difficult impeachment procedures for judges", "Appointment solely by the Prime Minister's personal decree", "Judges' salaries subject to daily parliamentary vote", "Executive control over court verdicts"], answer: 0, explanation: "Judges enjoy fixed tenure and can only be removed via rigorous impeachment under Article 124(4), insulating them from political pressure." },
    { subject: "Social Science", type: "Geography", tagText: "Black Soil", question: "Which type of soil, rich in clay and moisture retentive, is ideal for cotton cultivation in the Deccan Plateau?", options: ["Black Soil / Regur Soil (काळी रेगूर मृदा)", "Alluvial Soil", "Laterite Soil", "Red Soil"], answer: 0, explanation: "Black Regur soil derived from weathered basalt lava is rich in clay minerals, retaining moisture and ideal for growing cotton." },
    { subject: "Language", type: "Pedagogy", tagText: "Top-Down Reading", question: "In top-down reading processing, readers primarily rely on:", options: ["Prior background knowledge (schema) and contextual inference to comprehend meaning", "Individual phoneme-grapheme decoding alone", "Looking up every noun in a bilingual dictionary", "Tracing letter shapes with fingers"], answer: 0, explanation: "Top-down processing uses macro-level background knowledge, predictive hypotheses, and holistic context to make sense of text." },
    { subject: "Language", type: "Grammar", tagText: "Indirect Speech", question: "Change to reported speech: He said, 'I went to Delhi yesterday.'", options: ["He said that he had gone to Delhi the previous day.", "He said that he went to Delhi yesterday.", "He told he had gone to Delhi tomorrow.", "He says that he went to Delhi."], answer: 0, explanation: "Simple past 'went' shifts to past perfect 'had gone', and 'yesterday' becomes 'the previous day'." },
    { subject: "Language", type: "Vocabulary", tagText: "Antonym", question: "Choose the antonym of 'Ephemeral' (क्षणभंगुर/अल्पकालीन):", options: ["Eternal / Permanent (चिरंतन/कायमस्वरूपी)", "Transient", "Fleeting", "Short-lived"], answer: 0, explanation: "'Ephemeral' means lasting for a very short time; its antonym is 'Eternal' or 'Permanent'." },
    { subject: "Language", type: "Grammar", tagText: "Question Tags", question: "Select the correct question tag: 'Let's begin our project work, ____?'", options: ["shall we?", "will you?", "don't we?", "can we?"], answer: 0, explanation: "Imperative suggestions starting with 'Let's' take the conventional question tag 'shall we?'." },
    { subject: "Language", type: "Pedagogy", tagText: "Information Gap Activities", question: "Why are 'Information Gap' activities highly effective in communicative language classrooms?", options: ["They create a genuine necessity to communicate because one partner has information the other needs", "They keep students completely silent", "They focus on mechanical handwriting copying", "They test memory without speaking"], answer: 0, explanation: "Information gap tasks mirror authentic real-world communication by compelling learners to exchange unique information interactively." }
